(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-moe-skew-adaptive-dispatch"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-1\">一 · 一次尾延迟事故：被最慢分片钉住的解码步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-2\">二 · 算法定位：按层偏斜度切换核形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-3\">三 · 不解决什么：适用边界的三条硬线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-4\">四 · 代价结构：同步点、决策开销与 kernel 维护</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-5\">五 · 一个具体例子：热门专家单独成批的收益路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-6\">六 · 失败模式的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-7\">七 · 偏斜感知调度救不了什么：一次尾延迟放大的事故与三条失效线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-8\">八 · 计数归约：把路由结果变成可判定的直方图</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-9\">九 · 代价模型：三种候选配置的预估时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-10\">十 · 重排入队：热门单独成批、尾部合并成组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-11\">十一 · 执行：TMA 装载与 mbarrier 流水掩盖尾组启动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-12\">十二 · 回写与在线校正：让切换点跟着分布漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-13\">十三 · 跨层复用与决策点合并</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-14\">十四 · 切换判据的失效边界与同步开销账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-15\">十五 · 偏斜度量的定义与可计算性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-16\">十六 · 代价模型的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-17\">十七 · 系数在线校正的递推形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-18\">十八 · 伪代码：从直方图到 tile 队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-19\">十九 · 混合拆分的判据与一个具体算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-20\">二十 · 同步开销的量化位置与合并策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-21\">二十一 · 切换判据的失效边界与小 batch 下的同步税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-22\">二十二 · 负载配方：偏斜感知调度吃什么样的请求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-23\">二十三 · 并发与批大小：偏斜随 batch 增大而放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-24\">二十四 · 负载不对时会发生什么：三类失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-25\">二十五 · 配方与并行拓扑、量化的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-26\">二十六 · 配方校验清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-27\">二十七 · 负载配方：偏斜显著、批组成可观测的高并发短输出解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-28\">二十八 · 硬件档位：把 tcgen05 与 TMA 当作准入条件而非加分项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-29\">二十九 · 并行拓扑：专家并行与 All-to-All 的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-30\">三十 · 量化方案：NVFP4 权重激活与搬运量预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-31\">三十一 · KV 策略：解码相低延迟读取与权重加载的带宽隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-32\">三十二 · 调度参数：决策点合并与代价模型校正节奏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-33\">三十三 · 可复现配置思路：从标定到上线的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-34\">三十四 · 部署配方的边界条件：何时这套自适应调度会反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-35\">三十五 · 同步点的固定税：小 batch 下先崩的是决策开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-36\">三十六 · 显存与带宽：重排缓冲与权重搬运的争抢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-37\">三十七 · 通信：All-to-All 与决策同步的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-38\">三十八 · 功耗与利用率：被最慢分片钉住的 SM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-39\">三十九 · 尾延迟：切换点误判如何放大 P99</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-40\">四十 · 规模上限：先崩的顺序与容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-41\">四十一 · 精度问题：切换点判错与数值路径分叉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-42\">四十二 · OOM：专家权重与分页 KV 的带宽争抢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-43\">四十三 · 批抖动：小 batch 下同步开销占比失控</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-44\">四十四 · 路由不均与尾延迟尖刺的联合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-45\">四十五 · 监控埋点与回滚的分级设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-46\">四十六 · 候选 kernel 维护与编译产物膨胀的治理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-47\">四十七 · 切换点误判与同步开销：这套自适应调度的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-48\">四十八 · 对照轴：把同族算法放到同一张坐标系上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-49\">四十九 · 五条路线的分工与代价落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-50\">五十 · 决策表：按条件选路线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-51\">五十一 · 适用条件的量化边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-52\">五十二 · 组合而非替代：叠加顺序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-skew-adaptive-dispatch-sec-53\">五十三 · 偏斜自适应调度的失效边界与同族选型</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:558px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 557.5 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每层路由完成后在 GPU 上做计数归约，得到专家 token 直方图与偏斜…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">代价模型比较候选配置的预估时延：单专家大 tile、分组 GEMM、混合拆分</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按选择结果把 token 重排进对应 tile 队列，热门专家单独成批、尾…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">tcgen05 上以 TMA 加载权重与激活，分组 GEMM 用 mbar…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">执行后回写实测时延，在线校正代价模型系数</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">跨层复用偏斜统计，避免每层重复同步</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-1\">一 · 一次尾延迟事故：被最慢分片钉住的解码步</h3>\n<p>某在线服务在 B200 上部署一个专家数较多的 MoE 模型，解码阶段 batch 组成随请求到达动态变化，SLO 同时约束吞吐与 P99 尾延迟。上线初期配置是固定的：分组 GEMM 使用统一 tile 尺寸，所有专家走同一套核形态。压测时吞吐达标，但线上出现一种典型故障——平均 TPOT 正常，P99 却在流量高峰周期性抬升，且抬升与输入长度、输出长度都无强相关，只与并发批的组成相关。抓取单步时间线后定位到：某一层路由后，少数热门专家承载了该层大部分 token，而大量尾部专家各只分到个位数 token。固定 tile 下，热门专家需要排很多个 tile 串行执行，尾部专家则各自占用一个 tile 却几乎不干活。整层的完成时间由最慢的那条分片路径决定，SM 在尾部 tile 上大量空转，GPU 利用率被最慢分片拖住，单步时延被放大，尾延迟直接越线。</p>\n<p>这个事故的关键不在于“平均负载高”，而在于同一层内并行的粒度与真实分布不匹配。分组 GEMM 的设计假设是各专家 token 数大致可比，tile 切分后能均匀填满 SM；一旦分布长尾，固定 tile 就同时造成两种浪费：热门专家侧 tile 数过多带来的串行深度，以及尾部专家侧 tile 利用率过低带来的并行空转。更麻烦的是，这种偏斜是逐层、逐 batch 变化的，离线调参时选出的“平均最优”配置在偏斜层上必然失配。事故的修复不是加机器，而是让核形态跟着每层的路由分布走。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-2\">二 · 算法定位：按层偏斜度切换核形态</h3>\n<p>偏斜感知自适应核调度要解决的问题可以精确表述为：在 MoE 解码的每一层，依据该层路由计数的偏斜程度，在若干候选 kernel 配置之间做选择，使该层的预估执行时延最小。候选配置至少包括三类——单专家大 tile 密集 GEMM（适合热门专家单独成批、连续大块计算）、小 tile 分组 GEMM（适合大量小专家合并成组、并行填满 SM）、以及把热门专家与尾部专家拆开处理的混合拆分。判据由偏斜指标与代价模型共同给出：</p>\n<div class=\"formula\">$$S_l = \\frac{\\max_e n_{l,e}}{\\sum_e n_{l,e}},\\quad \\hat{T}(c) = \\alpha_c + \\beta_c \\sum_e \\lceil n_{l,e}/t_c \\rceil$$</div>\n<p>其中 $n_{l,e}$ 是第 $l$ 层专家 $e$ 的 token 数，$t_c$ 是配置 $c$ 的 tile 尺寸，$\\alpha_c,\\beta_c$ 为在线校正系数。$S_l$ 刻画最大专家占比，是“长尾有多长”的直接度量；$\\hat{T}(c)$ 把配置的代价拆成固定开销与按 tile 数累加的变动开销，$\\sum_e \\lceil n_{l,e}/t_c \\rceil$ 正是“最慢分片”的代理量——它统计的是需要串行执行的 tile 总数，而不是 token 总数。这个建模选择本身就说明算法盯的是并行深度而非总工作量：偏斜高时，大 tile 能压低热门专家的 tile 计数；偏斜低时，小 tile 能让尾部专家合并后仍填满 SM。</p>\n<p>与相邻方法的边界要划清：固定 tile 与固定分组配置是本方法的对照面，它不改变路由结果、不做令牌丢弃、不重设容量因子，也不涉及专家选择策略——那些属于路由侧条目的话题，此处只用一句话指路。本方法只接管“路由已经算完、token 已经知道去哪个专家”之后的核形态决策与 token 重排。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-3\">三 · 不解决什么：适用边界的三条硬线</h3>\n<p>第一条硬线是偏斜必须显著。当 $S_l$ 接近均匀分布时，各专家 token 数可比，固定分组 GEMM 已经能均匀填满 SM，切换带来的收益消失，反而多付一次决策与重排的开销。算法在偏斜接近均匀时应退化为不切换，这也是代价模型必须能识别“切换无益”的原因。</p>\n<p>第二条硬线是 batch 组成必须可观测且变化足够慢于决策周期。本方法依赖每层路由完成后的计数归约来获得直方图，若 batch 组成在层间剧烈抖动，上一层的偏斜统计对下一层没有预测力，跨层复用统计反而引入误判。它面向的是解码阶段高并发短输出的在线服务：批大小增大时偏斜更明显，收益也更稳定；小 batch 下每层同步开销占比高，需要合并决策点，收益被开销吃掉。</p>\n<p>第三条硬线是规模上限由工程成本决定。候选配置需要预先调优并维护多套 kernel，编译产物体积与调优负担随候选数上升；同步点数量随决策粒度上升。它不是“任何 MoE 解码都能提速”的通用开关，而是在偏斜显著、batch 可观测、且团队愿意承担多套 kernel 维护成本时的针对性手段。它也不解决权重带宽瓶颈本身——量化搬运的压缩属于 NVFP4/FP8 条目的范围，本方法只改变计算形态与并行填充方式。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-4\">四 · 代价结构：同步点、决策开销与 kernel 维护</h3>\n<p>按数据流顺序看代价落在哪里。每层路由完成后，先在 GPU 上做计数归约得到专家 token 直方图与偏斜指标，这一步是设备侧的小规模归约，代价随专家数增长但可控；随后主机侧读回指标、跑代价模型、比较单专家大 tile、分组 GEMM、混合拆分三种候选的预估时延，产生一个额外的同步点。同步点的代价在解码步里被放大：解码步本身只有微秒到毫秒级，一次主机往返与 kernel 启动的固定开销在小 batch 下占比高，这正是失败模式中“小 batch 下开销占比过高”的来源。</p>\n<p>选定配置后，token 需按选择结果重排进对应 tile 队列：热门专家单独成批、尾部专家合并成组。重排本身是访存操作，代价与 token 数成正比，但会打乱原本连续的激活布局，需要额外的索引与写回；在 tcgen05 上以 TMA 加载权重与激活时，重排后的队列必须保持 TMA 友好的块状布局，否则加载效率下降会抵消核形态切换的收益。分组 GEMM 侧用 mbarrier 流水掩盖尾组启动延迟，这是把“尾部专家合并成组后启动慢”的代价藏进流水里，而不是消除它。</p>\n<p>执行后回写实测时延、在线校正 $\\alpha_c,\\beta_c$，使代价模型跟随不同模型与 batch 组成的路由分布漂移。跨层复用偏斜统计以减少每层重复同步，是把多个决策点合并成一次的做法，代价是统计新鲜度下降。工程侧还有一笔常被低估的成本：候选 kernel 多套维护带来的编译产物体积与调优负担，以及系数失配或分布快速漂移时切换点判断错误导致核利用率回退甚至尾延迟放大的风险。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-5\">五 · 一个具体例子：热门专家单独成批的收益路径</h3>\n<p>设某层共 $E$ 个专家，batch 内 token 总数为 $N$，路由后最大专家占比 $S_l$ 明显偏高，热门专家拿到数百个 token，其余专家各只有个位数。固定小 tile 分组配置下，热门专家的 tile 计数为 $\\lceil n_{\\text{hot}}/t_{\\text{small}}\\rceil$，数值很大，形成长串行链；尾部专家各自一个 tile，SM 占用率极低。整层时延被热门专家的串行链钉住，尾部 tile 只是陪跑。</p>\n<p>切换到大 tile 单专家密集 GEMM 后，热门专家的 tile 计数降为 $\\lceil n_{\\text{hot}}/t_{\\text{large}}\\rceil$，串行深度显著缩短，且大 tile 下 MMA 的算术强度更高；尾部专家被合并成组走小 tile 分组路径，用 mbarrier 流水掩盖启动延迟。代价模型比较两种配置的 $\\hat{T}(c)$：大 tile 配置的 $\\beta_c\\sum_e\\lceil n_e/t_c\\rceil$ 因热门专家 tile 数下降而变小，但尾部专家若也走大 tile 会浪费，故混合拆分把两部分分开计价。最终选择使该层时延由“最慢分片”变为“热门专家大块计算 + 尾部合并填充”的并行结构，尾延迟收敛。这个例子的要点是：收益不来自更多算力，而来自把并行粒度对齐到真实分布。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-6\">六 · 失败模式的工程判断</h3>\n<p>三类失败模式都指向同一个判断：本方法的收益是“条件收益”，条件是偏斜显著且决策开销可摊薄。每层 GPU 计数归约与主机决策引入额外同步点，在小 batch 下开销占比高，工程上应合并决策点、跨层复用统计，并给代价模型设置“切换收益低于阈值则不切换”的死区，避免为微小收益付出同步代价。候选配置多套维护带来的编译产物体积与调优负担，要求候选集保持精简——三类配置已能覆盖长尾与均匀两端，盲目扩充候选只会推高调优成本。最危险的是系数失配或路由分布快速漂移时切换点判断错误：此时核利用率回退甚至尾延迟放大，比固定配置更差。因此在线校正必须与保守回退策略配对，实测时延偏离预估超过设定比例时退回默认配置，把自适应限制在可验证的范围内。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-7\">七 · 偏斜感知调度救不了什么：一次尾延迟放大的事故与三条失效线</h3>\n<p>某在线服务在 B200 上跑 MoE 解码，batch 从 8 涨到 64 时吞吐曲线突然塌陷：热门专家独占的 SM 早已满载，尾部专家分到的 tile 里只有零星几个 token，核空转却仍占着流水线槽位，整层时延被最慢分片钉死。运维按经验把分组 GEMM 的 tile 调大，热门专家更快了，尾部却因 tile 过大装不满而进一步浪费，尾延迟反而放大——这正是固定 tile、固定分组配置在偏斜路由下的典型死法。偏斜感知自适应核调度针对的就是这个具体问题：每层路由完成后在 GPU 上做计数归约得到专家直方图，用偏斜度 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 与代价模型 $\\hat T(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 在单专家大 tile、分组 GEMM、混合拆分之间切换，热门专家单独成批、尾部合并成组。但它只解决“偏斜显著且路由可观测”的那一段。</p>\n<p>第一条失效线是偏斜趋近均匀。当 $S_l$ 接近 $1/E$，各候选配置的预估时延差落入噪声区间，切换只带来重排 token 与切换 kernel 的固定开销，收益归零；此时应直接锁定单一配置，把决策点让给批调度。第二条是决策开销本身：每层 GPU 计数归约加主机侧决策引入额外同步点，小 batch 下这段开销占端到端时延的比例高到不可忽略，必须合并决策点、跨层复用偏斜统计，否则省下的核空转变成了同步等待。</p>\n<p>第三条最隐蔽：代价模型系数失配或路由分布快速漂移时，切换点判错会让核利用率回退甚至尾延迟放大，事故里那次“调大 tile”就是判错的一种。工程上应把在线校正后的 $\\alpha_c,\\beta_c$ 与实际时延的残差作为切换的置信门槛，残差超限时退回保守配置而非继续追最优。系统代价还体现在维护面：候选 kernel 需预先调优并维护多套，编译产物体积与调优负担随候选数线性上升，因此候选集应控制在少数几档，并与专家并行、All-to-All 拓扑、NVFP4/FP8 搬运量一起纳入容量规划。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>调度是否值得</th><th>代价落点</th></tr></thead><tbody><tr><td>偏斜显著、batch 组成可观测</td><td>值得，尾延迟收敛</td><td>每层归约与决策同步</td></tr><tr><td>偏斜接近均匀</td><td>不值得，收益消失</td><td>重排与切换固定开销</td></tr><tr><td>小 batch</td><td>需合并决策点</td><td>同步开销占比高</td></tr><tr><td>分布快速漂移</td><td>需置信门槛</td><td>判错导致尾延迟放大</td></tr></tbody></table>\n<p>边界因此可以写死：它适用于解码阶段 batch 组成动态变化、以吞吐与尾延迟双约束的在线服务，不适用于偏斜均匀的稠密路径、也不适用于无法承受每层同步的极小 batch；规模上限由候选配置调优成本与同步开销共同决定，而非由 tile 尺寸本身决定。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-8\">八 · 计数归约：把路由结果变成可判定的直方图</h3>\n<p>偏斜感知调度的第一步不是选核，而是把“这一层到底有多斜”变成一个能被代价模型消费的数字。路由（gate）在每层输出 top-k 专家索引之后，token 到专家的映射已经存在于寄存器与共享内存中，但它是分散的、按 token 排列的。调度器需要的是按专家排列的计数向量 $n_{l,e}$。做法是在 GPU 上做一次计数归约：每个 CTA 对自己负责的那段 token 做局部直方图（用共享内存的原子累加，专家数通常为 64/128/256，共享内存足以容纳整层直方图），再通过全局原子加或两级归约合并成层级的 $n_{l,e}$。归约的输入是 token 级专家索引，输出是一个长度等于专家数的整型向量，以及由它派生的两个标量指标：最大专家占比与基尼系数。</p>\n<p>这一步的代价必须算清楚。计数归约的访存量与 token 数成正比、与专家数成正比的分母无关，本质是一次 O(N) 的散射写；在解码阶段 N 就是 batch 内 token 数（含投机解码的草稿 token），量级很小，因此归约本身是微秒级的。真正的代价是它引入的同步点：归约完成前，主机侧无法做出配置选择，而选择结果又要传回 GPU 侧指导重排。也就是说，每层多了一次 GPU→Host 的指标回传与一次 Host→GPU 的配置下发。在小 batch 下，这两次往返的固定开销会占到该层执行时间的可观比例，这正是本方法必须做“跨层复用偏斜统计”的原因——把连续若干层的统计合并成一次决策，用层间路由分布的相关性换取同步次数的下降。</p>\n<p>具体例子：某层 128 个专家、batch 内 512 个 token，热门专家拿到其中约一半 token，则 $S_l \\approx 0.5$；若分布接近均匀，$S_l \\approx 1/128$。前者是典型的高偏斜，后者意味着切换收益消失。这个标量就是后续所有判断的入口。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-9\">九 · 代价模型：三种候选配置的预估时延</h3>\n<p>拿到直方图后，调度器要在候选配置集合 $\\mathcal{C}$ 上做一次 argmin。候选至少三类：单专家大 tile 密集 GEMM（适合热门专家，一个专家独占一个或多个大 tile，MMA 利用率高）、分组 GEMM（小 tile，把多个专家的 token 拼进同一组 tile，适合尾部）、以及混合拆分（热门专家走大 tile、尾部合并成组，两部分并发或串行拼接）。预估时延的形式是</p>\n<div class=\"formula\">$$\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\left\\lceil n_{l,e}/t_c\\right\\rceil$$</div>\n<p>其中 $t_c$ 是配置 $c$ 的 tile 尺寸（沿 token 维），$\\alpha_c$ 覆盖启动、TMA 描述符准备、mbarrier 初始化等固定开销，$\\beta_c$ 是单个 tile 的执行代价系数。求和项 $\\sum_e \\lceil n_{l,e}/t_c\\rceil$ 是关键：它把“每个专家被切成几个 tile”作为工作量度量，天然反映了尾部专家的浪费——当 $n_{l,e}$ 远小于 $t_c$ 时，向上取整仍然算一个整 tile，尾部专家越多、$t_c$ 越大，这个和就越被小专家的取整项撑大。这就是固定大 tile 配置在偏斜 batch 上被最慢分片拖住的数学表达。</p>\n<p>代价模型的输入是直方图与候选配置参数，输出是选中配置 $c^\\star$ 及其预估时延。它的系统代价不在计算（一次几十项的求和，纳秒级），而在参数可信度：$\\alpha_c,\\beta_c$ 若失配，切换点会判错，核利用率不升反降。因此 $\\alpha_c,\\beta_c$ 必须是在线校正量，而非编译期常量。工程上还要注意候选集合不能太大——每多一个候选就多一套 kernel 需要调优、编译、维护，编译产物体积与调优负担随候选数线性上升，这是该方法规模上限的直接来源。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-10\">十 · 重排入队：热门单独成批、尾部合并成组</h3>\n<p>配置选定后，token 必须按新形态重新组织。输入是原始 token 序列及其专家索引，输出是若干条 tile 队列：热门专家各自拥有一条以 $t_c$ 为粒度的队列（队内 token 连续排布，便于 TMA 以 2D 描述符整块搬运激活），尾部专家则按“凑满一个 tile”的原则合并成组，组内保留专家 id 以便分组 GEMM 的段表（segment table）寻址。重排本身是一次 scatter：读 token 索引、写目标偏移，访存量与 token 数成正比。</p>\n<p>这一步的隐藏代价是索引与元数据的构造。分组 GEMM 需要每组的起始偏移、每组内各专家的 token 数、以及权重指针数组；混合拆分还需要把热门部分与尾部分成两个独立的发射单元，各自有自己的 grid 维度。元数据量随专家数与组数增长，必须放在设备侧可被 TMA 直接读取的布局里，否则每次发射都要主机侧拼参数，同步开销立刻反噬。工程判断是：重排与元数据构造应尽量融合进归约后的同一个 kernel，避免额外的 kernel launch 与全局内存往返。</p>\n<p>具体例子：某层 512 token、热门专家 3 个各约 80 token，尾部 125 个专家各 1–3 token。大 tile 配置（$t_c=64$）下热门专家各占 2 个 tile、共 6 个 tile 高效执行，而尾部若也走 64-token tile 则要 125 个几乎全空的 tile；切到分组 GEMM 的小 tile（$t_c=16$）后尾部被压成约 8–16 个组，空转 tile 数大幅下降。混合拆分的意义就是把这两半同时放到各自最优的形态上。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-11\">十一 · 执行：TMA 装载与 mbarrier 流水掩盖尾组启动</h3>\n<p>执行阶段在 tcgen05 上展开。权重与激活通过 TMA 以张量描述符整块搬入共享内存，再由 tcgen05 MMA 从共享内存（或经 TMEM 中转）消费。对单专家大 tile 路径，权重块是规则的、可预取的，TMA 的多级流水能把搬运完全藏在 MMA 之后。对分组 GEMM 路径，难点在“尾组启动延迟”：每个组都要重新绑定权重指针、重新计算段表偏移，组与组之间的切换会暴露流水气泡。缓解手段是用 mbarrier 把组间的依赖解耦——上一组的 MMA 尚未结束时，下一组的 TMA 装载已经可以发起，用异步屏障而不是全局同步来串接，从而把尾组的启动开销压进前一组的数据搬运窗口里。</p>\n<p>这一步的系统代价集中在带宽与占用上。NVFP4/FP8 的权重与激活把搬运量按位宽比例压低，使得同样带宽下能喂饱更多 tile；但 KV cache 的低延迟读取与权重装载共享同一条 HBM 通路，解码阶段 KV 读取是刚性需求，若权重预取过于激进就会与 KV 争抢带宽，表现为尾延迟抖动。因此执行阶段的调度要显式区分优先级：KV 读取走低延迟路径，权重 TMA 预取深度按剩余带宽预算收敛。功耗侧，大 tile 路径的 MMA 密度高、单位时间算力利用率高，分组路径的 tile 小、启动频繁，单位有效工作的能耗更差——这也是偏斜低时不应盲目切到分组 GEMM 的原因之一。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-12\">十二 · 回写与在线校正：让切换点跟着分布漂移</h3>\n<p>每次执行结束，实测时延被回写到代价模型，用于更新 $\\alpha_c,\\beta_c$。输入是选中配置 $c^\\star$、预估时延 $\\hat{T}(c^\\star)$、实测时延 $T^{\\text{real}}$；输出是校正后的系数。最朴素的做法是对残差做指数滑动平均：$\\alpha_c \\leftarrow \\alpha_c + \\eta\\,(T^{\\text{real}}-\\hat{T}(c))$，$\\beta_c$ 同理按 tile 数归一后更新。校正的意义在于路由分布会漂移——不同模型、不同 batch 组成、不同请求混合比都会改变直方图形状，编译期固定的切换点很快失效。校正的代价是必须持续采样实测时延，而时延采样本身需要 GPU 侧计时器与主机侧聚合，又是一次跨设备通信；工程上通常按固定周期而非每层回写，把校正频率与决策频率解耦。</p>\n<p>失败模式在这里最集中：系数失配或路由分布快速漂移时，切换点判断错误会让核利用率回退，甚至因为多了一次错误形态的发射而放大尾延迟。防御手段是给切换加迟滞（hysteresis）——预估时延差小于某个阈值时不切换，避免在两个配置间抖动；同时保留一个保守的兜底配置，在模型置信度低时退回固定分组 GEMM。</p>\n<p>具体例子：连续若干层的 $S_l$ 从 0.5 滑向 0.1，若不校正，模型仍按高偏斜选大 tile，尾部空转重新出现；校正后 $\\beta_{\\text{group}}$ 的相对优势被实测数据放大，切换点随之前移，配置跟着分布走。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-13\">十三 · 跨层复用与决策点合并</h3>\n<p>单层决策的同步开销在小 batch 下无法摊薄，因此机制的最后一步是把决策从“每层一次”降为“每若干层一次”。输入是连续 $k$ 层的路由统计，输出是一组共享的配置选择；实现上可以在第一次归约时顺带累加后续层的直方图（若路由在时间上已可见），或直接用前 $k$ 层的统计外推后 $k$ 层的偏斜。复用的前提是层间路由分布具有相关性——同一 batch 内相邻层的热门专家集合往往重叠，这使得外推的误差可控。代价是决策粒度变粗：某一层突然变均匀时，复用的高偏斜配置会多跑一层，产生一次性的利用率损失，这是用少量精度换同步开销的典型权衡。</p>\n<p>决策点合并还影响候选 kernel 的维护策略。既然决策频率下降，候选集合可以收敛到 2–3 个真正有区分度的配置，而不是为每个 tile 尺寸都维护一套；编译产物体积与调优矩阵随之收缩。工程判断落在这一点上：偏斜感知调度的收益上界由路由偏斜度决定，而其可行性上界由同步开销与候选维护成本决定；在 batch 很小、层数很多、SLO 以尾延迟为硬约束的在线服务里，把决策点合并到跨层粒度、把候选收敛到少数几套经过实测校正的 kernel，比追求每层最优更能稳住尾延迟。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-14\">十四 · 切换判据的失效边界与同步开销账</h3>\n<p>这套机制真正的脆弱点不在“选哪个核”，而在“什么时候不该选”。切换判据建立在偏斜度 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 与代价模型 $\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 之上，而 $\\alpha_c$ 里含着启动与流水填充的固定项。当 batch 很小、每层 token 总数只有几十个时，$\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 的量化误差与 $\\alpha_c$ 同量级，两个候选配置的预估时延差落在噪声带内，此时任何切换都是掷硬币。工程上必须设一个死区：仅当 $\\hat{T}(c^\\star)$ 相对次优配置的领先幅度超过阈值（例如按实测抖动方差折算的百分比）才执行切换，否则沿用上一层决策。偏斜接近均匀时收益本就消失，死区同时兼作这一边界的守卫。</p>\n<p>代价的另一半是同步。每层路由完成后要在 GPU 上做计数归约，再把直方图与偏斜指标搬到主机侧做决策，这构成一个额外的 kernel 边界加一次设备到主机回读；在连续批处理下它插在注意力与 MoE 之间，直接把层间流水切断。小 batch 解码时单层计算只有微秒级，这一次同步的占比被放大到不可忽略。缓解手段是跨层复用偏斜统计：连续若干层共用一次归约结果与一次决策，把决策点从“每层”降为“每 N 层”，代价是切换滞后于真实路由漂移。N 的选取本身就是吞吐与尾延迟的折中——N 大则同步省、响应钝；N 小则跟得紧、开销高。</p>\n<p>第三类失效来自系数失配。$\\alpha_c,\\beta_c$ 靠执行后回写实测时延在线校正，但校正用的是历史样本，而在线服务的 batch 组成在高并发短输出形态下逐迭代变化。若路由分布快速漂移（例如某请求触发长尾专家集中激活），旧系数给出的切换点会系统性偏错，结果是热门专家被塞进分组 GEMM 的小 tile、或尾部专家被强行拉进单专家大 tile，核利用率不升反降，尾延迟被最慢分片重新拖住。因此校正必须带遗忘因子并对残差设上限，一旦实测与预估的偏差连续超出带宽就退回保守配置。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>机制表现</th><th>系统代价</th></tr></thead><tbody><tr><td>小 batch、层内 token 少</td><td>预估时延差落入噪声带</td><td>同步开销占比高，切换无收益</td></tr><tr><td>偏斜接近均匀</td><td>两配置时延趋同</td><td>切换收益消失，仅剩决策开销</td></tr><tr><td>路由分布快速漂移</td><td>系数失配、切换点判错</td><td>核利用率回退、尾延迟放大</td></tr><tr><td>候选配置多套维护</td><td>编译产物膨胀</td><td>调优与验证负担、产物体积上升</td></tr></tbody></table>\n<p>还有一层隐性代价落在带宽上：token 重排进 tile 队列、热门专家单独成批、尾部专家合并成组，这些搬运本身要读写激活；在 NVFP4/FP8 量化下权重搬运量已压缩，激活重排的相对占比反而上升，且要与 KV cache 的低延迟读取争抢带宽。判断这套方案是否值得上线，看的不是平均吞吐，而是“同步开销 + 重排搬运”能否被热门专家不再被尾部拖慢所释放的利用率覆盖——在偏斜显著且 batch 组成可观测的解码场景里成立，在偏斜平坦或 batch 极小的场景里则应直接退回固定配置。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-15\">十五 · 偏斜度量的定义与可计算性</h3>\n<p>偏斜感知调度的第一步不是选核，而是把“偏斜”变成一个能在 GPU 上低成本算出来的标量。给定第 <i>l</i> 层路由完成后的专家 token 直方图 <i>n<sub>l,e</sub></i>，定义最大专家占比</p>\n<div class=\"formula\">$$S_l=\\frac{\\max_e n_{l,e}}{\\sum_e n_{l,e}}$$</div>\n<p>这个量的取值范围被专家数 <i>E</i> 夹住：均匀路由时 <i>S<sub>l</sub></i> ≈ 1/<i>E</i>，全部 token 压到一个专家时趋近 1。选它而不是基尼系数作为主判据，理由是实现代价：基尼系数需要对直方图排序或做两两差分，在每层解码路径上做排序归约意味着额外的共享内存往返与同步；而 <i>S<sub>l</sub></i> 只需要一次 max 归约加一次 sum 归约，两者都能在路由计数归约的同一个 kernel 里用 warp shuffle 完成，结果写回一个全局标量。工程上把 max 与 sum 合并进计数归约的尾部，避免第二次启动。</p>\n<p>可计算性还体现在精度上。计数归约的输入是路由输出的 one-hot 索引，用 int32 累加即可，不存在浮点非确定性；<i>S<sub>l</sub></i> 用 fp32 做一次除法，误差量级远小于切换判据的间隔。真正需要小心的是<b>归约的粒度</b>：若按 (token, top-k) 展平后计数，top-k 中同一 token 命中多个专家会重复计入分母，导致 <i>S<sub>l</sub></i> 被系统性低估，切换点偏向分组 GEMM。正确做法是分母取实际参与计算的 token-专家对总数，而非 batch 内 token 数。</p>\n<p>代价上，这次归约的规模是 <i>B·k</i> 个索引，在解码 batch 下通常只有几千到几万个元素，单次归约在数十微秒量级；但它插在路由与专家计算之间，是一个串行依赖点，因此其绝对时延不重要，重要的是它不能被隐藏。这正是后面要把跨层复用与合并决策点写进伪代码的原因。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-16\">十六 · 代价模型的逐项拆解</h3>\n<p>候选配置 <i>c</i> 的预估时延写成</p>\n<div class=\"formula\">$$\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\left\\lceil\\frac{n_{l,e}}{t_c}\\right\\rceil$$</div>\n<p>逐项看：<i>t<sub>c</sub></i> 是配置 <i>c</i> 的 tile 尺寸，即一个 MMA tile 覆盖的 token 数；<i>⌈n<sub>l,e</sub>/t<sub>c</sub>⌉</i> 是专家 <i>e</i> 需要发射的 tile 数，向上取整意味着不足一个 tile 的尾部也要占满一个 tile 的发射开销；求和是对所有被激活的专家；<i>β<sub>c</sub></i> 是每个 tile 的平均执行代价，<i>α<sub>c</sub></i> 是与 tile 数无关的固定开销——kernel 启动、TMA 描述符准备、mbarrier 初始化、尾组排空。</p>\n<p>这个形式的关键一步是把“最慢分片决定整体”这件事编码进了求和而非取 max。分组 GEMM 在单流上顺序发射各专家的 tile，总时延近似为 tile 总数乘以单 tile 代价，因此求和是合理的一阶模型；而单专家密集 GEMM 走的是另一条路径：热门专家单独成批后，其 tile 数被压到很少，但每个 tile 的 <i>β<sub>c</sub></i> 更高（大 tile、更高算术强度、更长的流水），<i>α<sub>c</sub></i> 也更低（无需分组调度与尾组处理）。两个配置的 <i>α</i>、<i>β</i> 不同，正是切换能产生收益的来源。</p>\n<p>推导中容易被忽略的一步是<b>向上取整的偏斜放大效应</b>。设 <i>E</i> 个专家、总 token 数 <i>N</i>，均匀时每个专家 <i>N/E</i> 个 token，tile 总数约为 <i>E·⌈N/(E·t)⌉</i>；而在最大占比 <i>S</i> 的偏斜下，热门专家贡献 <i>⌈S·N/t⌉</i> 个 tile，其余 <i>E−1</i> 个专家即使每个只有个位数 token，也各贡献至少一个 tile。于是 tile 总数从“与 <i>N/t</i> 同阶”变成“被 <i>E</i> 个尾组的下界钉住”。这就是固定 tile 配置下 GPU 利用率被最慢分片拖住的数学表述：尾组不是慢在计算，而是慢在<b>每个尾组都要付一次固定的发射与排空代价</b>。<i>t<sub>c</sub></i> 越小，尾组的浪费越小但 tile 总数越多；<i>t<sub>c</sub></i> 越大，热门专家越高效但尾组越浪费。切换判据就是在这个权衡上找交点。</p>\n<p>把两个候选相减，切换条件可写成</p>\n<div class=\"formula\">$$\\hat{T}(c_{\\text{dense}})&lt;\\hat{T}(c_{\\text{group}})\\iff \\beta_d\\sum_e\\left\\lceil\\frac{n_{l,e}}{t_d}\\right\\rceil-\\beta_g\\sum_e\\left\\lceil\\frac{n_{l,e}}{t_g}\\right\\rceil&lt;\\alpha_g-\\alpha_d$$</div>\n<p>左侧是 tile 代价差，右侧是固定开销差。由于 <i>t<sub>d</sub></i> &gt; <i>t<sub>g</sub></i>，左侧随偏斜上升而下降（热门专家 tile 数被大 tile 压缩），因此存在一个由 <i>S<sub>l</sub></i> 单调决定的交点。工程上不必解析求解，直接把 <i>S<sub>l</sub></i> 分档查表即可，表项由在线校正后的 <i>α</i>、<i>β</i> 重新计算。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-17\">十七 · 系数在线校正的递推形式</h3>\n<p><i>α<sub>c</sub></i>、<i>β<sub>c</sub></i> 不是静态常量。路由分布随 batch 组成漂移、量化后的权重搬运量随专家命中变化、TMA 流水在不同 tile 数下的掩盖效率也不同，因此必须用实测时延回写。最小可实现的形式是对每个配置维护一对指数滑动平均：</p>\n<div class=\"formula\">$$\\beta_c\\leftarrow(1-\\eta)\\,\\beta_c+\\eta\\cdot\\frac{T^{\\text{obs}}_c-\\alpha_c}{\\sum_e\\lceil n_{l,e}/t_c\\rceil},\\qquad \\alpha_c\\leftarrow(1-\\eta)\\,\\alpha_c+\\eta\\cdot\\left(T^{\\text{obs}}_c-\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil\\right)$$</div>\n<p>先更新 <i>β</i> 再更新 <i>α</i> 的顺序不能颠倒：<i>β</i> 的估计依赖当前 <i>α</i>，若同时更新两者，固定开销会被错误地摊进单 tile 代价，导致小 tile 数场景下 <i>β</i> 被高估、切换点向分组 GEMM 偏移。实践中更稳的做法是只在 tile 总数超过某阈值的样本上更新 <i>β</i>，因为 tile 数太少时 <i>α</i> 与 <i>β</i> 的可辨识性差。</p>\n<p>校正的代价是每层一次实测时延回写，需要 GPU 侧时间戳（如 <i>clock64</i> 或 CUDA event）与主机侧或设备侧的小状态更新。若把状态放在设备端常量内存并由下一个 kernel 读取，可避免主机往返；但更新本身要与决策读取做顺序保证，否则会用旧系数做新决策。这里的工程判断是：<b>校正频率应低于决策频率</b>，例如每若干层或每若干 batch 更新一次系数，而每层只做查表决策，把同步开销压到决策路径之外。</p>\n<p>失败模式在此处很具体：当路由分布快速漂移（例如 batch 内请求类型突变导致热门专家换人），滑动平均的滞后会使 <i>β</i> 仍反映旧分布，切换点判断错误，核利用率回退甚至尾延迟放大。缓解手段是给 <i>η</i> 设一个随预测残差自适应的下界，残差持续偏大时提高 <i>η</i>，让模型更快跟上。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-18\">十八 · 伪代码：从直方图到 tile 队列</h3>\n<p>把上述公式落到可实现的控制流，需要明确三件事：计数归约与决策的放置、候选配置的比较顺序、重排与 tile 队列的构造。下面给出单层的主干伪代码，省略具体 kernel 内部实现。</p>\n<p>第一阶段，路由输出后立即在 GPU 上做计数归约，得到直方图 <i>hist[E]</i> 与 <i>S<sub>l</sub></i>：</p>\n<ul>\n<li>以 <i>B·k</i> 个专家索引为输入，warp 内 shuffle 归约，块内共享内存累加，跨块用原子加写全局 <i>hist</i>；</li>\n<li>同一 kernel 尾部对 <i>hist</i> 做 max 与 sum 归约，写出 <i>S<sub>l</sub></i> 与总对数 <i>N<sub>pairs</sub></i>；</li>\n<li>若启用跨层复用，则把 <i>S<sub>l</sub></i> 写入环形缓冲，供后续若干层直接读取，跳过重复归约。</li>\n</ul>\n<p>第二阶段，决策：</p>\n<ul>\n<li>读入候选配置表（单专家大 tile、分组 GEMM、混合拆分），对每个候选按 <i>hist</i> 计算 tile 总数 <i>Σ<sub>e</sub>⌈n<sub>e</sub>/t<sub>c</sub>⌉</i>；</li>\n<li>用当前 <i>α<sub>c</sub></i>、<i>β<sub>c</sub></i> 算 <i>T̂(c)</i>，取 argmin；若最小与次小之差小于阈值，保持上一层的选择以避免抖动；</li>\n<li>小 batch 下合并决策点：连续若干层只做一次决策，用这几层 <i>S<sub>l</sub></i> 的最大值作为保守估计。</li>\n</ul>\n<p>第三阶段，重排与队列构造：</p>\n<ul>\n<li>按决策结果把 token 索引散射进对应 tile 队列：热门专家单独成批，队列长度为其 tile 数乘以 <i>t<sub>c</sub></i>；</li>\n<li>尾部专家按 <i>n<sub>e</sub></i> 升序合并成组，每组填充到一个 tile，组内不足 <i>t<sub>c</sub></i> 的位置用无效索引占位并在 MMA 后屏蔽；</li>\n<li>为每个 tile 队列生成 TMA 描述符，权重按专家偏移加载，激活按队列索引 gather。</li>\n</ul>\n<p>第四阶段，执行与回写：tcgen05 上以 TMA 加载权重与激活，分组 GEMM 用 mbarrier 流水掩盖尾组启动延迟——即在前一组 MMA 未完成时预取下一组权重，使尾组的 <i>α</i> 被部分隐藏；kernel 结束时记录实测时延并按第三节递推更新系数。</p>\n<p>这段伪代码的代价集中在两处：计数归约与决策之间的串行依赖，以及重排散射的额外显存流量。前者在解码路径上是纯延迟，后者与 KV cache 读取争抢带宽——因此重排应复用路由阶段已写出的索引缓冲，避免二次读写。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-19\">十九 · 混合拆分的判据与一个具体算例</h3>\n<p>候选配置里的“混合拆分”不是第三种独立核，而是把一次前向拆成两段：热门专家走大 tile 单专家密集 GEMM，尾部专家走小 tile 分组 GEMM。它的预估时延是两段之和减去可重叠部分：</p>\n<div class=\"formula\">$$\\hat{T}_{\\text{hyb}}=\\hat{T}_{\\text{dense}}(E_{\\text{hot}})+\\hat{T}_{\\text{group}}(E_{\\text{tail}})-\\gamma\\cdot\\min\\!\\left(\\hat{T}_{\\text{dense}},\\hat{T}_{\\text{group}}\\right)$$</div>\n<p>其中 <i>γ</i> 是两段在两条流上并发执行时的重叠比例，受 SM 占用与 TMA 带宽约束，通常小于 1。混合拆分的收益条件是尾部专家的 tile 数占比不可忽略、且两段的 SM 需求之和不超过可用 SM 数；否则并发退化为串行，<i>γ</i> 趋零，反而不如单一配置。</p>\n<p>给一个不依赖具体硬件的定性算例：设某层 <i>E</i> 个专家、总对数 <i>N<sub>pairs</sub></i>，最大专家占比 <i>S<sub>l</sub></i> 接近 0.5，即一半 token 压在一个专家上。分组 GEMM 配置下，热门专家贡献约 <i>0.5N/t<sub>g</sub></i> 个 tile，其余专家各至少一个 tile，tile 总数被尾组下界抬高；单专家大 tile 配置下，热门专家的 tile 数被压缩到约 <i>0.5N/t<sub>d</sub></i>，尾组仍需各自发射，但 <i>α<sub>d</sub></i> 更低。此时若 <i>β<sub>d</sub></i> 与 <i>β<sub>g</sub></i> 接近，密集配置胜出；若量化后权重搬运使 <i>β<sub>d</sub></i> 明显更高（大 tile 单次搬运量更大、TMA 事务更长），交点会向分组 GEMM 移动。这正是系数必须在线校正而不能写死的原因。</p>\n<p>反过来，当 <i>S<sub>l</sub></i> 接近 1/<i>E</i>（路由接近均匀），两个配置的 tile 总数都接近 <i>N/t</i>，切换收益消失，此时应固定选择维护成本更低的那一个，把决策开销也省掉。这条边界与适用边界一致：偏斜不显著时，自适应本身成为负担。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-20\">二十 · 同步开销的量化位置与合并策略</h3>\n<p>公式里没有显式出现同步项，但它是这套方法在小 batch 下的主要代价来源。把每层决策的额外开销记为 <i>T<sup>sync</sup></i>，则实际每层时延为 <i>T̂(c<sup>★</sup>) + T<sup>sync</sup></i>，切换的净收益为</p>\n<div class=\"formula\">$$\\Delta=T̂(c_{\\text{fixed}})-T̂(c^\\star)-T^{\\text{sync}}$$</div>\n<p>只有当 <i>Δ</i> 为正时切换才值得。小 batch 下 <i>T̂</i> 本身很小，<i>T<sup>sync</sup></i> 占比升高，<i>Δ</i> 容易转负——这就是失败模式里“小 batch 下开销占比过高”的定量表述。合并决策点是对 <i>T<sup>sync</sup></i> 的直接压缩：把 <i>m</i> 层合并为一次决策，同步开销摊薄为 <i>T<sup>sync</sup>/m</i>，代价是用这几层中最坏的 <i>S<sub>l</sub></i> 做保守选择，可能在某些层选了次优配置。</p>\n<p>跨层复用偏斜统计是另一半：若相邻层的路由分布高度相关（同一 batch 的请求类型在层间稳定），则可跳过若干层的计数归约，只保留决策。跳过归约省下的是 GPU 侧归约时间与其后的依赖等待，但引入了统计滞后；判断是否可跳过的依据是历史层间 <i>S<sub>l</sub></i> 的相关系数，相关系数高则跳过多层，低则逐层归约。</p>\n<p>工程判断落在最后这一步：这套方法的可实现性不取决于公式多精细，而取决于<b>决策点能否被移出关键路径</b>。把计数归约与决策做成与上一层专家计算重叠的异步任务、把系数校正放到 batch 边界、把候选配置表编译期固化以减少运行时分支，三者合起来才能让小 batch 场景下 <i>Δ</i> 保持为正。反之，若每层都强制一次主机侧同步决策，即便偏斜显著，收益也会被同步吞掉。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-21\">二十一 · 切换判据的失效边界与小 batch 下的同步税</h3>\n<p>公式里真正决定成败的不是 $\\hat T(c)$ 的主项，而是 $\\alpha_c$ 与 $\\beta_c$ 的在线校正质量。$\\alpha_c$ 吸收的是配置 $c$ 的固定开销——尾组启动、mbarrier 流水填充、TMA 首段延迟；$\\beta_c$ 则绑定每 tile 的有效吞吐。当路由分布快速漂移（例如连续批处理中一批长请求刚退出、一批短请求涌入），历史窗口内的实测时延不再代表当前配置，$\\beta_c$ 被低估时模型会过度偏爱大 tile 单专家路径，把尾部专家重新塞回慢分片；被高估时则退回分组 GEMM，热门专家的核利用率白白丢掉。失效判据可以写成一个相对误差阈值：当 $|\\hat T(c_1)-\\hat T(c_2)|/\\min(\\hat T(c_1),\\hat T(c_2))&lt;\\epsilon$ 时，切换本身不产生收益，应保持上一层的选择以省掉一次决策同步。</p>\n<p>同步税的量级必须显式建模。每层一次 GPU 计数归约加主机侧决策，意味着一次 device-to-host 回传与一次 kernel 启动间隙；在小 batch、高并发短输出的解码形态下，单层计算本身只有几十微秒量级，这次同步可能占到层时延的可观比例。工程上的做法是把决策点从“每层”降为“每 k 层”并跨层复用偏斜统计——用第 $l$ 层的直方图外推第 $l+1$ 层，仅在 $S_l$ 越过阈值或实测时延偏离预测超过容差时才重新决策。代价是外推误差：层间路由相关性弱时，复用会把错误配置带进下一层。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>切换收益</th><th>主要代价</th></tr></thead><tbody><tr><td>偏斜显著（$S_l$ 高）、batch 大</td><td>热门专家脱离尾组拖累，尾延迟收敛</td><td>多套 kernel 的调优与产物体积</td></tr><tr><td>偏斜接近均匀</td><td>收益消失，两种配置时延接近</td><td>决策同步纯属浪费</td></tr><tr><td>小 batch、层时延短</td><td>被同步开销抵消</td><td>归约与主机决策占比过高</td></tr><tr><td>分布快速漂移</td><td>系数失配导致判断错误</td><td>核利用率回退、尾延迟放大</td></tr></tbody></table>\n<p>还有一个容易被忽略的耦合项：NVFP4/FP8 量化下权重搬运量下降，$\\beta_c$ 对 tile 尺寸的敏感度随之改变——大 tile 单专家路径的收益更多来自减少分组调度开销而非带宽节省，因此量化档位切换后必须重新标定 $\\beta_c$，否则代价模型会在错误的切换点上稳定振荡。边界判断应落在“偏斜可观测且层时延足以摊薄一次同步”这一条上；越过这条边界，固定配置反而是更稳的工程选择。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-22\">二十二 · 负载配方：偏斜感知调度吃什么样的请求</h3>\n<p>偏斜感知自适应核调度不是通用加速器，它的收益完全由 batch 内路由分布的形态决定。负载配方可以拆成四个可观测维度：请求形态、长度分布、并发水平、批大小。这四个维度共同决定每层专家 token 直方图 $n_{l,e}$ 的偏斜度 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$，而 $S_l$ 正是切换判据的唯一输入。换句话说，调度器并不关心请求内容，它只关心这些请求在每一层被路由成了什么形状。工程上判断一个服务是否适合上这套机制，等价于判断它的 $S_l$ 分布是否长期落在高偏斜区间、且 batch 组成是否在毫秒级可观测。</p>\n<p>适合的请求形态是<strong>高并发短输出的在线解码服务</strong>：对话补全、分类打标、结构化抽取、路由分发这类单次输出几十到几百 token 的负载。它们的共同特征是解码步数少、每步都要做一次全层前向，因此每层的路由计数归约与主机决策开销可以被摊薄到相对较多的并发请求上；同时短输出意味着请求周转快，batch 组成在秒级内反复变化，偏斜统计天然具有动态性，固定 tile 配置必然在某些时刻失配。反过来，长输出、低并发的批处理任务（离线摘要、长文生成）每步 batch 很小、解码步数极多，每层一次同步点的代价会直接压在关键路径上，这类负载应留在固定配置路径上。</p>\n<p>长度分布的要求更细：输入长度决定预填阶段的 token 总量，输出长度决定解码阶段的步数。偏斜感知调度作用在解码阶段，因此需要<strong>输入长度分布相对集中、输出长度短且方差小</strong>。若输入长度长尾严重，预填与解码的 piggyback 会让解码 batch 的组成被预填请求污染，专家直方图在层间抖动加剧，代价模型的在线校正系数 $\\alpha_c,\\beta_c$ 追不上漂移。工程判断是：把偏斜感知调度绑定在纯解码 batch 上，预填请求走独立通道，这与分块预填/解码 piggyback 的边界一致，本片段不展开。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-23\">二十三 · 并发与批大小：偏斜随 batch 增大而放大</h3>\n<p>批大小是负载配方里最敏感的一项。MoE 解码的路由是逐 token 逐层独立的，batch 内 token 数越多，热门专家聚集的绝对数量越大，$S_l$ 越容易逼近 1。小 batch 时 token 数少，直方图本身噪声大，$S_l$ 在层间跳动，但绝对偏斜未必高；大 batch 时统计稳定、偏斜显著，正是单专家大 tile 密集 GEMM 占优的区间。这就是为什么负载配方把<strong>中大批量、持续高并发</strong>列为甜点区：batch 足够大，热门专家能填满大 tile，尾部专家合并成组的浪费被摊薄。</p>\n<p>代价模型给出的判据是配置 $c$ 的预估时延</p>\n<div class=\"formula\">$$\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\left\\lceil n_{l,e}/t_c\\right\\rceil$$</div>\n<p>其中 $t_c$ 是配置 $c$ 的 tile 尺寸。求和项对每个专家取上整，意味着任何非零 token 数的专家都至少占用一个 tile。小 batch 下大量专家 $n_{l,e}$ 为 0 或 1，上整带来的固定开销占比极高，分组 GEMM 的尾组启动延迟被 mbarrier 流水掩盖也救不回来；此时切换收益消失，甚至因为多一次决策同步而净亏。大 batch 下 $\\lceil n_{l,e}/t_c\\rceil$ 对热门专家接近线性、对尾部专家趋近 1，大 tile 配置把热门专家的 tile 数压到最少，收益才成立。</p>\n<p>具体例子：一个 64 专家、top-2 路由的 MoE 解码层，batch=8 时每层约 16 个 token 路由，直方图里多数专家计数为 0 或 1，$S_l$ 可能只有 0.2 上下，分组 GEMM 与单专家大 tile 的预估时延差落在噪声内；batch=256 时约 512 个路由 token，若前 4 个专家吃掉六成 token，$S_l$ 接近 0.6，大 tile 配置把热门专家的 tile 数从分组配置的十余个压到个位数，尾部专家合并成一组，预估时延差拉开到足以覆盖决策同步开销。工程上应设置一个 batch 下限阈值，低于阈值直接走固定配置、跳过决策，把同步点从每层一次降为每若干层一次。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-24\">二十四 · 负载不对时会发生什么：三类失配</h3>\n<p>第一类失配是<strong>偏斜接近均匀</strong>。当路由分布被负载均衡损失或专家容量因子压平，$S_l$ 落在低位，单专家大 tile 配置失去意义，切换判据在两个候选间来回抖动，每层都做一次无收益的决策。此时系统付出计数归约与主机同步的固定成本，却拿不到任何核利用率改善，尾延迟反而因为决策点插入而变差。适用边界写得很清楚：偏斜接近均匀时切换收益消失。工程上的对策是给切换加迟滞，用跨层复用的偏斜统计做滑动判断，避免逐层翻转。</p>\n<p>第二类失配是<strong>batch 组成快速漂移</strong>。在线服务的请求到达是泊松式的，batch 在连续批处理下每步都可能换人。若漂移速度快于代价模型在线校正的收敛速度，$\\alpha_c,\\beta_c$ 的估计滞后于真实分布，切换点判断错误会导致核利用率回退甚至尾延迟放大。这不是理论风险：解码每步只有毫秒级，一次错误的配置选择会让该步被最慢分片拖住，而连续批处理把这一步的延迟传导到所有在飞请求。对策是把偏斜统计的复用粒度从单层拉到跨层，用前几层的直方图预测后续层的形态，减少每层独立决策带来的抖动。</p>\n<p>第三类失配是<strong>小 batch 高并发假象</strong>。并发数高不等于单步 batch 大：若每个请求输出极短、周转极快，任意时刻在飞的 token 数可能仍然很小，batch 被拆得很碎。此时每层 GPU 计数归约与主机决策的开销占比过高，同步点成为瓶颈。这类负载看起来符合“高并发短输出”的形态描述，实际 batch 却落在甜点区之下，属于配方误判。判断依据应是在飞 token 数的分布而非请求并发数。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-25\">二十五 · 配方与并行拓扑、量化的耦合</h3>\n<p>负载配方不能脱离并行拓扑单独谈。偏斜感知调度在专家并行下才有意义：专家被切分到不同 rank，All-to-All 把 token 送到目标专家所在设备，每层的本地直方图只是全局直方图的一个分片。若专家并行度高、单卡只承载少量专家，本地 $S_l$ 会被切分放大，热门专家在单卡上的占比更高，大 tile 配置的收益更明显，但 All-to-All 的通信量也随之上升。负载配方要求 batch 组成可观测，本质是要求 All-to-All 的收发计数能被调度器读到，否则偏斜统计只能靠本地近似。分离式专家并行把通信与计算解耦后，偏斜统计的观测点需要跟着搬，这是配方落地时必须对齐的部署细节。</p>\n<p>量化与负载配方的耦合在搬运量上。NVFP4/FP8 权重与激活把单次 tile 加载的字节数压低，tcgen05 上以 TMA 加载权重与激活时，大 tile 配置的权重搬运成本相对下降，热门专家单独成批的收益被放大；但同时 KV cache 按解码相低延迟读取，若 KV 读取与权重加载争抢带宽，大 tile 配置的 TMA 流水会被打断，mbarrier 掩盖尾组启动延迟的效果打折。负载配方因此要求 KV cache 的读取路径与专家权重加载在带宽上错峰，这一点与分页 KV 和专家权重共存显存的设计直接相关，本片段只指出耦合方向。</p>\n<p>具体例子：一个 GB200 NVL72 上的专家并行部署，单卡承载 8 个专家、batch=128、top-2 路由，每层本地约 32 个路由 token。若其中 2 个本地专家吃掉七成本地 token，本地 $S_l$ 接近 0.7，单专家大 tile 配置把这两个专家的 tile 数压到最少；剩余 6 个专家合并成一组走小 tile 分组 GEMM。若把专家并行度提高一倍、单卡只承载 4 个专家，本地 token 数减半，直方图噪声上升，切换判据的稳定性下降，配方需要相应提高 batch 下限或拉长统计窗口。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-26\">二十六 · 配方校验清单与工程判断</h3>\n<p>把负载配方落成可执行的校验清单，比笼统说“适合在线服务”更有用。校验项应覆盖：在飞 token 数的分布是否长期高于 batch 下限；每层 $S_l$ 的高分位是否稳定落在切换判据的收益区间；请求输出长度方差是否足够小以保持解码 batch 纯净；专家并行度下单卡本地直方图的噪声是否在可接受范围；KV 读取与权重加载的带宽是否错峰。任一项不满足，就应把该流量切到固定配置路径，而不是让自适应调度在失配区间空转。</p>\n<p>工程判断的核心是<strong>把决策开销当作负载配方的一部分来预算</strong>。每层一次 GPU 计数归约加主机决策，在毫秒级解码步上不是免费操作；候选配置多套维护带来的编译产物体积与调优负担，也要计入部署成本。配方正确的标志不是“切换次数多”，而是“切换发生在收益明确的层、且同步开销被 batch 摊薄”。当 batch 落在甜点区、偏斜显著且组成可观测时，这套机制把热门专家从尾部专家的拖累中解放出来；当配方不对，它退化成每层插一个同步点的固定配置，尾延迟比不用还差。因此上线前应先跑偏斜分布画像，用实测直方图确定 batch 下限与迟滞窗口，再决定是否开启逐层决策。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-27\">二十七 · 负载配方：偏斜显著、批组成可观测的高并发短输出解码</h3>\n<p>这套调度只在一种请求形态里划算：在线服务、解码阶段、高并发短输出，且每层路由计数能在 GPU 侧低成本拿到。判据用偏斜度 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 与代价模型 $\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 共同决定切换点；$S_l$ 接近均匀（如 $1/E$ 量级）时，单专家大 tile 与分组 GEMM 的预估时延差被 $\\alpha_c$ 吃掉，切换收益消失，此时应直接锁定一种配置、把决策点合并到跨层复用里。批大小是关键变量：批增大时热门专家 token 更集中、$S_l$ 抬升，切换才有意义；小 batch 下每层计数归约加主机决策的固定开销占比过高，必须把多层决策合并成一次，否则省下的核空转抵不过同步代价。</p>\n<p>负载不对时的失效是双向的。请求形态若是长输出、低并发（如离线批推理），batch 组成稳定、偏斜长期不变，自适应每层重算只是白付同步成本；若并发高但长度分布极短且路由近乎均匀，切换点判断会在两种配置间抖动，实测时延回写把 $\\alpha_c,\\beta_c$ 拉来拉去，核利用率回退甚至尾延迟放大。更隐蔽的一种是路由分布快速漂移（如多租户混跑不同领域 prompt），代价模型系数失配使 $c^\\star$ 选错，热门专家被塞进小 tile、尾部专家被拆进大 tile，最慢分片反而更慢。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>决策</th><th>系统代价</th></tr></thead><tbody><tr><td>高并发短输出、$S_l$ 高</td><td>逐层切换，热门专家单独成批</td><td>同步点开销被吞吐摊薄，尾延迟收敛</td></tr><tr><td>小 batch、$S_l$ 中等</td><td>合并多层决策点</td><td>归约与主机决策占比高，收益被抵消</td></tr><tr><td>偏斜近均匀</td><td>锁定单一配置</td><td>多套 kernel 维护与编译产物体积成纯负担</td></tr></tbody></table>\n<p>工程判断落在容量规划上：候选配置（单专家大 tile、分组 GEMM、混合拆分）需预先调优并随模型版本维护，编译产物与调优工时是硬上限；SLO 以吞吐与尾延迟双约束时，应把切换决策的同步开销计入时延预算，而不是假设它免费。KV cache 按解码相低延迟读取配置、NVFP4/FP8 降低搬运量，都是为了让权重加载不与 KV 读取争抢带宽——否则 TMA 流水掩盖的尾组启动延迟会被内存争用重新暴露。规模上限由此确定：偏斜可观测、批组成动态但可统计、候选配置数量可控，三者同时成立才值得上这套调度。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-28\">二十八 · 硬件档位：把 tcgen05 与 TMA 当作准入条件而非加分项</h3>\n<p>本方法的部署起点不是“有没有 GPU”，而是“这一代加速器是否同时具备 tcgen05 的 tensor memory 通路与 TMA 的批量搬运能力”。原因很直接：候选配置里“单专家大 tile 密集 GEMM”依赖 tcgen05 的 2-SM MMA 形态把热门专家的权重与激活压进 TMEM，尾组的分组 GEMM 则依赖 TMA 把多组小权重拼成一次异步加载，并用 mbarrier 流水掩盖尾组启动延迟。缺任何一项，候选配置集合就从三种退化成一种，切换逻辑失去意义。</p>\n<p>档位划分按“每 SM 可用 TMEM 容量 × 单卡 HBM 带宽 × NVLink 域规模”三轴做，而不是按型号名。工程上落成一张准入表：能跑单专家大 tile 的档位记为 A 档，只能跑分组 GEMM 的记为 B 档，两者都不满足的档位直接退回固定配置基线。A 档要求单层专家权重在 NVFP4 下能被 TMA 以足够大的 tile 一次搬入，否则大 tile 配置的 $\\alpha_c$ 项（固定启动开销）摊不薄，代价模型会持续选它却拿不到收益。B 档则相反，$\\beta_c$ 项主导，靠小 tile 提高并行度。</p>\n<p>代价落在编译产物上：每个档位要维护独立的候选 kernel 集合。A 档至少两套（大 tile 密集、混合拆分），B 档至少一套（分组 GEMM），加上基线固定配置，产物体积与调优工时随档位数线性增长。因此档位不宜按 SKU 细分，按“能否容纳最大专家 tile”二分即可，把省下的工程量留给代价模型系数校正。</p>\n<p>具体例子：一个 NVL72 机架内混布 A 档与 B 档节点时，调度层必须把同一层的偏斜决策绑定到节点档位——同一 batch 的 token 不能跨档位拆分到不同 kernel 形态，否则 All-to-All 之后的重排队列会与 kernel 选择错位。做法是把档位写进并行拓扑的 rank 元数据，决策在档位内闭合。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-29\">二十九 · 并行拓扑：专家并行与 All-to-All 的耦合约束</h3>\n<p>并行拓扑的第一约束来自本方法自身：偏斜统计是“每层、每专家”的计数直方图，只有在专家并行组内做归约才有意义。若专家被切到不同 rank，$n_{l,e}$ 必须先在 EP 组内 all-reduce 成全局直方图，再算 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$。这一步与 All-to-All 的 dispatch 可以合并：dispatch 本身就要按专家目的 rank 分桶，桶大小即 $n_{l,e}$ 的本地分量，归约搭在 dispatch 的通信上，边际成本接近零。</p>\n<p>第二约束是 TP 与 EP 的配比。单专家大 tile 配置在 TP 组内做张量切分时，热门专家的激活复制到每个 TP rank，TMEM 占用按 TP 度线性上升；分组 GEMM 配置则倾向把尾组专家整体放在单 rank 上以减少跨 rank 同步。于是拓扑要允许“热门专家 TP 切分、尾部专家 EP 独占”的混合布局，这要求权重放置阶段就按预期偏斜预分片——但偏斜是运行时的，预分片只能按历史统计做，部署配方里必须留一条权重重排通道。</p>\n<p>代价是通信量：混合布局下热门专家的 All-to-All 是 TP 组内广播，尾部专家是 EP 组间点对点，NVLink 5 域内的带宽分配不均，容易出现热门专家通信排队而尾部链路空闲。工程判断是给热门专家路径预留更高的 NCCL 通道优先级，把尾部专家的合并组通信压到低优先级队列，用 NIXL 的点对点语义绕开集合通信的全局同步。</p>\n<p>具体例子：EP=8、TP=2 的 16 卡拓扑，某层 $S_l$ 达到高位（少数专家承载大部分 token）时，热门专家走 TP=2 切分 + 组内广播，尾部专家按 EP 独占合并成组；同一层 $S_l$ 回落到接近均匀时，全部专家退回 EP 独占 + 分组 GEMM，避免 TP 广播的固定开销。拓扑不变，变的是每层的通信路径选择，这与 kernel 选择共用同一个决策点。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-30\">三十 · 量化方案：NVFP4 权重激活与搬运量预算</h3>\n<p>量化方案直接决定候选配置的可行性边界。NVFP4 权重与激活把每 token 每专家的搬运字节压到 FP8 的一半，使单专家大 tile 配置能在同样的 TMA 带宽预算下搬入更大的 tile，$\\beta_c$ 项随之下降。但微缩放粒度带来额外元数据：每 16 或 32 个元素一组 scale，分组 GEMM 的尾组因为 tile 小，scale 元数据占比反而升高，抵消部分收益。</p>\n<p>部署配方按“权重 NVFP4、激活 NVFP4、累加 FP32”为主方案，理由是热门专家路径的瓶颈在权重搬运而非算力，NVFP4 的搬运收益最直接；对数值敏感的层（如路由 logits 前的投影）保留 FP8，代价是这些层不能进单专家大 tile 候选，只能走分组 GEMM。这形成一张按层的量化—配置联合表：量化精度与候选 kernel 集合绑定，决策时先查表再算代价。</p>\n<p>代价模型要吸收量化差异：$\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 中的 $\\beta_c$ 实际是“每 tile 的搬运时间 + 计算时间”，NVFP4 下搬运项缩小而计算项不变，因此 $\\beta_c$ 的在线校正必须按量化方案分组维护系数，不能全局共用一套。系数失配是本方法明确的失败模式之一，量化切换会让失配立刻显形。</p>\n<p>具体例子：同一层在 FP8 与 NVFP4 下各跑一次，实测时延回写后若发现 NVFP4 的 $\\beta_c$ 未按预期下降，说明该层 tile 尺寸受 TMEM 容量而非带宽限制，应把该层从大 tile 候选剔除，改走分组 GEMM。这是部署期一次性标定，不是运行时决策。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-31\">三十一 · KV 策略：解码相低延迟读取与权重加载的带宽隔离</h3>\n<p>KV cache 策略的核心矛盾是带宽争抢：解码相每步都要读全量 KV，而本方法的候选配置切换会在同一 step 内触发权重 TMA 加载。两者共享 HBM 带宽时，KV 读取的尾延迟会被权重加载拉长，尾延迟约束直接失守。部署配方要求 KV 与专家权重在物理上分离——分页 KV 走独立的显存池，专家权重常驻另一池，靠页表与权重描述符分别寻址，避免同一次 TMA 事务里混读。</p>\n<p>KV 侧按解码相低延迟配置：页大小取与 attention kernel 的 tile 对齐的粒度，减少每步的页表遍历次数；KV 分页池按请求粒度动态扩缩，长输出请求的 KV 增长不触发权重池的换出。这里不复述分页 KV 与专家权重共存的显存布局细节，只强调本方法新增的一条：每次 kernel 配置切换都要重排 token 队列，重排后的 token 顺序会改变 KV 的访问局部性，因此 KV 页的物理排布要按“专家分组后的 token 序”做一次轻量重映射，否则切换带来的局部性损失会吃掉 kernel 收益。</p>\n<p>代价是显存：权重池按最大专家 tile 预留，KV 池按并发请求上限预留，两池之和不能超过单卡容量，否则触发换出。工程判断是权重池按 A 档最大 tile 预留、B 档节点按分组 GEMM 的最大组预留，档位不同预留不同，不做统一。</p>\n<p>具体例子：高并发短输出场景下，KV 池增长快但单请求 KV 短，页表遍历开销占比低；此时若权重池预留过大挤占 KV，会迫使 KV 换出，尾延迟反而恶化。配方给出的做法是权重池按档位固定预留、KV 池弹性增长，弹性上限由 SLO 的尾延迟目标反推。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-32\">三十二 · 调度参数：决策点合并与代价模型校正节奏</h3>\n<p>调度参数分三组：决策频率、同步粒度、校正节奏。决策频率默认“每层一次”，但小 batch 下每层 GPU 计数归约 + 主机决策的同步开销占比过高，配方要求按 batch 大小合并决策点——batch 低于阈值时改为每 N 层决策一次，跨层复用偏斜统计，用上一层直方图近似本层，代价是切换点判断滞后一层。这是明确的失败模式边界：偏斜在层间快速变化时，复用会误判。</p>\n<p>同步粒度上，计数归约留在 GPU 侧完成，只把直方图与 $S_l$ 标量回传主机，不回传逐 token 路由结果，把同步数据量压到常数级。主机侧决策只做候选配置的代价比较与队列重排指令下发，重排本身在 GPU 侧按预生成的索引执行，避免主机参与数据搬运。</p>\n<p>校正节奏按“执行后回写实测时延、按滑动窗口更新 $\\alpha_c,\\beta_c$”配置，窗口长度取能覆盖一次路由分布漂移的量级；校正只调系数不改候选集合，候选集合的增删走部署期标定。这样把在线复杂度锁在系数更新上，避免运行时编译新 kernel。</p>\n<div class=\"formula\">$$\\hat{T}(c)=\\frac{1}{\\kappa_c}\\sum_{e}\\left\\lceil\\frac{n_e}{B_c}\\right\\rceil t^{\\text{tile}}_c+\\lambda\\,T^{\\text{launch}}_c,\\quad c^\\star=\\arg\\min_c \\hat{T}(c)$$</div>\n<p>式中 $\\kappa_c$ 是配置 $c$ 的有效并行度折算，$\\lambda$ 是启动开销权重，两者都是校正对象。部署配方要求 $\\lambda$ 按档位分别标定：A 档启动开销被大 tile 摊薄，$\\lambda$ 小；B 档分组 GEMM 组数多，$\\lambda$ 大，若共用一套 $\\lambda$ 会系统性偏向大 tile。</p>\n<p>具体例子：一个 batch 组成在数十步内从均匀漂移到高度偏斜的在线服务，滑动窗口校正若长于漂移时间，$\\beta_c$ 滞后导致切换点判断错误，核利用率回退、尾延迟放大——这正是列出的失败模式。配方给出的参数是窗口长度取漂移时间的一半量级，并在检测到 $S_l$ 阶跃变化时强制触发一次全量重标定。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-33\">三十三 · 可复现配置思路：从标定到上线的顺序</h3>\n<p>可复现的关键是把“候选集合、量化、拓扑、KV、调度参数”五者按依赖顺序固化，而不是并行调。顺序是：先定档位与候选 kernel 集合（决定编译产物），再定量化—配置联合表（决定每层可用的候选子集），再定并行拓扑与通信路径（决定归约与重排的落点），再定 KV 与权重池的显存切分（决定带宽隔离），最后标定调度参数与代价模型系数。</p>\n<p>标定阶段产出三样东西：每档位每候选配置的 $\\alpha_c,\\beta_c$ 初值；每层的量化—候选映射表；决策点合并的 batch 阈值。上线阶段只允许系数在线更新，其余固化。回归测试用固定 batch 组成跑一遍，检查切换点是否落在预期层，以及尾延迟是否收敛。</p>\n<ul>\n<li>档位准入：tcgen05 + TMA 双具备才进 A 档，否则退基线。</li>\n<li>候选集合：A 档两套、B 档一套，按档位编译，不跨档共用。</li>\n<li>量化：权重激活 NVFP4 为主，敏感层 FP8 并绑定分组 GEMM 候选。</li>\n<li>拓扑：EP 组内归约搭 dispatch，热门专家 TP 切分、尾部 EP 独占。</li>\n<li>KV：与权重分池，按专家分组后的 token 序做页重映射。</li>\n<li>调度：小 batch 合并决策点，GPU 侧归约只回传标量，系数滑动窗口校正。</li>\n</ul>\n<p>工程判断落在最后一条：这套配方的稳定性不取决于候选 kernel 多寡，而取决于决策点与通信路径是否共用同一个每层同步。把归约、重排、通信路径选择压进一次 GPU 侧计数与一次主机侧决策，同步开销才是常数级；任何把这些拆成多次同步的实现，都会在小 batch 下被开销吞掉收益，退化成固定配置基线。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-34\">三十四 · 部署配方的边界条件：何时这套自适应调度会反噬</h3>\n<p>这套配方成立的前提是偏斜可观测且显著。硬件档位必须落在支持 tcgen05 与 TMA 的加速器上，否则大 tile 单专家 GEMM 的收益根本兑现不了；并行拓扑要配合专家并行与 All-to-All，量化走 NVFP4/FP8 权重与激活把搬运量压下来，KV cache 按解码相低延迟读取配置、避免与权重加载争抢带宽。判据是偏斜度 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 与代价模型 $\\hat T(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$：$S_l$ 接近均匀分布时，单专家大 tile 与分组 GEMM 的预估时延差收敛到噪声量级，切换收益消失，此时应退回固定分组 GEMM，把决策点合并到跨层复用统计里。失效条件是路由分布快速漂移——在线校正系数 $\\alpha_c,\\beta_c$ 滞后于真实时延，切换点判错会让核利用率回退、尾延迟放大，这比不切换更糟。</p>\n<p>系统代价集中在同步与工程体积两处。每层 GPU 侧计数归约加主机侧决策引入额外同步点，小 batch 下这笔开销占比高，必须把多层的决策点合并成一次批量提交，用跨层偏斜统计摊薄；候选 kernel 多套并存意味着编译产物体积与调优负担上升，每套配置都要单独预热与实测回写。一个具体例子：高并发短输出的在线服务里，批大小增大时偏斜更明显，热门专家单独成批、尾部专家合并成组后，tcgen05 上 TMA 加载权重与激活、mbarrier 流水掩盖尾组启动延迟；但若某层路由突然趋于均匀，大 tile 队列空转，代价模型必须在一个校正周期内切回分组形态。</p>\n<table class=\"mini\"><thead><tr><th>边界</th><th>触发信号</th><th>处置</th></tr></thead><tbody><tr><td>偏斜趋均匀</td><td>$S_l$ 低于切换阈值</td><td>锁定分组 GEMM，停用大 tile 候选</td></tr><tr><td>小 batch</td><td>同步开销占比超预算</td><td>合并多层决策点</td></tr><tr><td>分布漂移</td><td>实测与预估时延偏离</td><td>加速系数校正、暂缓切换</td></tr></tbody></table>\n<p>工程判断落在规模上限：候选配置的调优成本与同步开销共同约束可部署的层数与 batch 区间，超出这个区间就该退化为静态配置而非逐层自适应。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-35\">三十五 · 同步点的固定税：小 batch 下先崩的是决策开销</h3>\n<p>偏斜感知调度的代价结构里，有一项与负载无关的固定支出：每层路由完成后必须在 GPU 侧做计数归约，把直方图与偏斜指标搬到主机侧（或至少是另一个 kernel 的启动边界），再由代价模型做出选择。这条链路上至少存在一次设备同步与一次额外的 kernel 启动，两者都不随 batch 缩小而缩小。解码阶段单层单 token 的计算量本就极薄，当 batch 只有几十条序列时，热门专家可能只拿到个位数的 token，一个 tile 都填不满，此时决策开销在层时延中的占比会显著上升。</p>\n<p>把这一项写进代价模型才能看清崩点。设每层决策的固定开销为 $T^{\\text{sync}}$（含归约 kernel、主机往返、重排索引生成），则实际层时延为</p>\n<div class=\"formula\">$$T_l = \\hat{T}(c^\\star_l) + T^{\\text{sync}}_l,\\qquad \\text{speedup}_l = \\frac{T^{\\text{fixed}}_l}{\\hat{T}(c^\\star_l) + T^{\\text{sync}}_l}$$</div>\n<p>分子是固定配置下的层时延，分母多出的那一项就是税。切换收益来自分子与 $\\hat{T}(c^\\star)$ 的差，只有当这个差大于 $T^{\\text{sync}}$ 时，逐层决策才是正收益。工程上的直接推论是决策点必须合并：跨层复用偏斜统计，把若干层的直方图一次性归约、一次性决策，用批量化的主机交互摊薄固定开销。合并的代价是决策滞后——用第 $l$ 层的统计去指导第 $l+2$ 层的核形态，在路由分布层间相关性强的模型上误差可控，在层间专家分工差异大的模型上则会把切换点判断错。这是一条明确的工程取舍线，而不是可以两边都占的优化。</p>\n<p>具体例子：一个 batch 为 32 条序列的解码步，若每层决策引入的同步与启动开销相当于若干微秒量级，而该层热门专家密集 GEMM 的实际执行只有同等量级，则逐层切换不但不赚，反而把层时延拉长。此时正确做法是退回固定配置、只在跨层粒度上做一次切换判断，或干脆在低 batch 区间禁用自适应路径。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-36\">三十六 · 显存与带宽：重排缓冲与权重搬运的争抢</h3>\n<p>调度决策落地时要付出显存代价。按选择结果把 token 重排进对应 tile 队列，意味着需要一块按配置尺寸组织的索引与激活暂存区：热门专家单独成批需要连续的大 tile 缓冲，尾部专家合并成组需要一张组内偏移表。这块缓冲的容量由最大候选配置的 tile 尺寸决定，而不是由当前实际 token 数决定——因为配置是预先编译好的，缓冲必须按最坏情况预留。多套候选 kernel 并存还带来权重侧的压力：单专家密集 GEMM 与分组 GEMM 对权重布局的要求不同，若不做布局转换就需要保留两份视图，或在切换时付出一次重排成本。</p>\n<p>带宽侧的争抢更隐蔽。tcgen05 路径上权重与激活经 TMA 加载，分组 GEMM 用 mbarrier 流水掩盖尾组启动延迟；这条流水线的稳定前提是权重搬运带宽不被其他流量挤占。解码阶段 KV cache 的低延迟读取与权重加载共享同一份 HBM 带宽，当 batch 增大、KV 读取量上升时，留给专家权重搬运的余量收窄，尾组的流水填充变得更脆弱。量化在这里不是可选项而是前提：NVFP4/FP8 权重与激活把搬运量压下来，才使得在 KV 流量存在的情况下仍能维持 TMA 流水的深度。</p>\n<p>规模上去以后先崩的往往不是算力而是这块缓冲的占用弹性。候选配置越多、tile 尺寸跨度越大，预留缓冲越大，可留给 KV cache 的显存越少，进而压低可支撑的并发序列数——这是一条从调度灵活性反向侵蚀吞吐容量的路径。判断标准很直接：当预留重排缓冲与多套权重视图占用的显存超过 KV cache 预算的某个比例时，增加候选配置的边际收益转负。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-37\">三十七 · 通信：All-to-All 与决策同步的叠加</h3>\n<p>在专家并行拓扑下，本方法的同步开销不是孤立的一项，而是叠加在 All-to-All 之上。路由完成后的计数归约本身可以在本地分片上做，但全局直方图需要跨 rank 归约才能得到真实的 $S_l$；若每个 rank 独立决策，各 rank 可能选出不同配置，导致同一层内不同分片的核形态不一致，重排后的 token 队列在跨 rank 交换时无法对齐 tile 边界。因此实践中要么做一次跨 rank 的偏斜指标广播，要么接受各 rank 独立决策并在交换阶段做一次格式归一。</p>\n<p>前者的代价是一次小消息集合通信，其延迟在 NVLink 5 域内相对可控，但它把决策点钉在了通信屏障上：所有 rank 必须等到最慢的那个完成本地归约。后者的代价是交换阶段的格式转换，等价于在 All-to-All 的有效载荷上增加一次重排。两种方案的代价都随专家并行度上升而放大——rank 数越多，屏障等待的方差越大，独立决策的不一致概率越高。</p>\n<p>吞吐上的表现是：当系统从单机扩展到 NVL72 级别的多机域，跨机 All-to-All 的时延占比上升，此时每层决策引入的额外同步会被通信延迟放大成可观的尾延迟抖动。工程判断是：在跨机域内应把决策粒度从逐层放宽到逐块（若干层一组），并把偏斜统计的归约搭在已有的 All-to-All 通信上 piggyback，而不是新开一条同步路径。这与分离式部署中预填与解码的通信安排是同一类问题，只是这里的载荷是几个标量而非激活。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-38\">三十八 · 功耗与利用率：被最慢分片钉住的 SM</h3>\n<p>固定配置下的核心问题是利用率被最慢分片拖住：热门专家的核满载，尾部专家的核在空转但仍在耗电。空转的 SM 不产生有效吞吐，却维持着时钟与漏电功耗，因此固定配置的能效比在偏斜显著时明显劣化。自适应切换把尾部专家合并成组，本质上是把空转的核释放出来，让同一份功耗预算产出更多 token。</p>\n<p>但切换本身也有功耗代价。大 tile 单专家密集 GEMM 让少量 SM 长时间高负载运行，局部功耗密度上升，可能触发时钟回退；分组 GEMM 把负载摊到更多 SM 上，单核功耗下降但总活跃核数上升。两种形态的功耗分布不同，在机架级功耗封顶的部署里，选择哪一种不只是时延问题，还牵涉到能否在功耗墙内维持目标频率。这一点在 GB200/GB300 NVL72 这类整机架部署中尤其敏感：机架功耗是共享预算，单机的高功耗密度会挤压同机架其他节点的频率空间。</p>\n<p>具体例子：某层偏斜度 $S_l$ 接近 1（几乎全部 token 落在单一专家），固定分组 GEMM 会让绝大多数组的核空转；切到单专家大 tile 后有效核数下降但每个核的利用率接近饱和，层时延下降的同时空转功耗被消除。反之当 $S_l$ 接近 $1/E$（均匀），单专家路径退化为大量小规模启动，启动开销与低占用率同时出现，此时分组 GEMM 才是能效更优的一侧。切换判据因此不能只看时延，还要把功耗密度纳入代价模型的系数校正。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-39\">三十九 · 尾延迟：切换点误判如何放大 P99</h3>\n<p>吞吐是均值问题，尾延迟是方差问题，而本方法的失败模式恰恰是方差放大器。代价模型系数 $\\alpha_c,\\beta_c$ 靠执行后回写实测时延在线校正，校正本身有滞后；当路由分布快速漂移（例如请求组成从短输出问答突变为长上下文摘要，专家热度排序整体翻转），滞后期间的切换点判断会错，选中的配置在该层实际表现劣于固定配置，核利用率回退。</p>\n<p>更严重的是这种误判不是均匀分布的，它倾向于集中在分布切换的过渡层上，也就是那些 $S_l$ 处于两个候选配置收益交叉点附近的层。这些层的时延在相邻解码步之间来回跳变，形成双峰分布，P99 被推高而均值几乎不变——监控上表现为吞吐正常但 SLO 违约。设过渡层集合为 $\\mathcal{L}^\\star$，尾延迟的放大可近似写成</p>\n<div class=\"formula\">$$\\Delta P_{99}\\approx \\sum_{l\\in\\mathcal{L}^\\star}\\left|T_l(c_{\\text{wrong}})-T_l(c^\\star)\\right|$$</div>\n<p>控制手段是给切换加迟滞：只有当新配置的预估收益超过一个阈值（覆盖模型误差与同步税）时才真正切换，避免在交叉点附近抖动。迟滞的代价是过渡期内的次优选择，但换来的是尾延迟收敛，这与本方法宣称的“尾延迟收敛”并不矛盾——收敛的前提正是迟滞与在线校正共同压制了抖动。</p>\n<p>工程上还要区分两种尾延迟来源：一种是单层切换误判造成的层内抖动，靠迟滞解决；另一种是跨层决策合并造成的滞后，靠缩短统计复用窗口解决。两者方向相反，调参时必须分开观测，否则会把滞后误诊为误判，越调越糟。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-40\">四十 · 规模上限：先崩的顺序与容量规划</h3>\n<p>把上述代价按规模排序，可以得到一条明确的崩溃顺序。最先崩的是小 batch 区间的同步税：batch 越小，$T^{\\text{sync}}$ 占比越高，自适应路径的净收益越早转负。第二崩的是候选配置维护成本：每增加一套 kernel，编译产物体积、调优工时、验证矩阵都线性上升，而收益只在特定偏斜区间内兑现，边际收益递减很快。第三崩的是跨 rank 决策一致性：专家并行度上升后，全局归约的屏障方差与独立决策的不一致概率同时放大。最后崩的才是显存与带宽：预留重排缓冲与多套权重视图挤压 KV cache 预算，KV 流量与权重搬运争抢 HBM 带宽。</p>\n<p>这个顺序对容量规划的直接含义是：不要按峰值 batch 去配置候选集，而应按服务实际运行的 batch 分布中位数去裁剪候选集——把只在极端偏斜下才有收益的配置砍掉，换取更小的编译产物与更低的调优负担。同时把决策粒度与并行域绑定：单机域内可逐层决策，跨机域内必须降级为逐块决策并 piggyback 到已有通信上。</p>\n<p>规模上限的定量判据可以写成一条净收益不等式：</p>\n<div class=\"formula\">$$\\underbrace{\\mathbb{E}\\left[T^{\\text{fixed}}_l-T_l(c^\\star)\\right]}_{\\text{切换收益}}&gt;\\underbrace{T^{\\text{sync}}_l+\\gamma\\,C_{\\text{maint}}}_{\\text{固定税与维护摊销}}$$</div>\n<p>左侧随偏斜度上升而增大、随 batch 增大而增大；右侧的同步项随并行度上升，维护项随候选集规模上升。当服务规模扩大导致右侧增长快于左侧时，就该收缩候选集或放宽决策粒度，而不是继续加配置。这条不等式也是判断“规模上去以后哪里先崩”的操作性工具：分别测量左右两侧随 batch、并行度、候选数的斜率，斜率先交叉的那一项就是当前的瓶颈。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-41\">四十一 · 精度问题：切换点判错与数值路径分叉</h3>\n<p>偏斜感知核调度本身不改写数值，但它把同一层的 token 送进两条不同的数值路径：偏斜高时走单专家大 tile 密集 GEMM，偏斜低时走分组 GEMM。两条路径的累加顺序、tile 切分边界、以及 NVFP4/FP8 微缩放的块划分都可能不同，于是同一份权重在不同配置下产生不同的舍入轨迹。工程上最先暴露的症状不是整层输出崩坏，而是长尾请求的输出出现低频重复、标点漂移或工具调用参数抖动——这类问题在吞吐指标上完全看不见，只有逐请求比对才抓得到。</p>\n<p>诊断的核心是把“配置选择”当成一个可观测变量打进日志。每次决策记录三元组（层号、选中配置 c、偏斜指标 S_l），并与该层的实测时延、输出 token 的校验和一起落盘。当出现精度回归时，先看回归样本经过的层是否集中在某几个 c 上；若是，则问题在 kernel 实现而非调度逻辑。判据上可用一个轻量的一致性检查：对同一 batch 用固定配置 c0 重放一次，比较两条路径输出的最大绝对偏差，超过阈值即判定该 c 的数值路径不可用于生产。</p>\n<div class=\"formula\">$$\\Delta_{\\max}=\\max_{i}\\left|y_i^{(c)}-y_i^{(c_0)}\\right|,\\quad \\text{reject } c \\text{ if } \\Delta_{\\max}&gt;\\tau_{\\text{num}}$$</div>\n<p>代价在于重放本身：一次固定配置重放等于把该层算两遍，在解码路径上直接翻倍该层时延。因此一致性检查只能抽样、只能离线或只在灰度流量上开启，不能进主链路。另一个具体机制是让两条路径共享同一份微缩放因子布局，把块大小对齐到 tile 尺寸的整数倍，从源头消除分叉；这要求候选 kernel 在编译期就约定好量化块的排布，属于部署配方里必须提前锁死的东西。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-42\">四十二 · OOM：专家权重与分页 KV 的带宽争抢</h3>\n<p>本方法的显存失败很少是“装不下”，而是“装得下但抢不到带宽”。热门专家单独成批意味着这些专家的权重被高频重复加载，若权重未常驻则每次决策切换都可能触发一次权重重排；同时解码相的分页 KV 按低延迟读取配置，两者在同一 HBM 通道上竞争。表现为：显存占用看着还有余量，但 kernel 启动前的 TMA 加载排队时间变长，尾延迟尖刺与 OOM 告警同时出现。</p>\n<p>监控上要区分“分配失败”与“带宽饱和”。分配失败看 allocator 的 reserved 与 peak 差值；带宽饱和看每层 TMA 加载的 stall 计数与 HBM 读写吞吐占额定带宽的比例。一个可操作的判据是把每层决策后的权重加载字节数累加，与 KV 读取字节数做比：</p>\n<div class=\"formula\">$$\\rho_l=\\frac{V^{\\text{wt}}_l}{V^{\\text{wt}}_l+V^{\\text{kv}}_l},\\quad \\text{alert if } \\rho_l \\text{ 在连续 } k \\text{ 层超过阈值}$$</div>\n<p>当 ρ_l 持续偏高，说明调度把太多热门专家拆成独立批、反复搬运权重，此时应回退到分组 GEMM 配置或提高合并阈值，让尾部专家与热门专家共享一次权重加载。具体例子：某层路由直方图显示单个专家占比超过一半，调度选单专家大 tile，权重加载量随之抬升；若该层同时处于长上下文解码、KV 分页读取密集，两条流叠加就会把该层时延推高一个档位。回滚动作是把该层的配置白名单临时收窄到分组 GEMM，并把偏斜统计的复用窗口拉长，减少决策频率。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-43\">四十三 · 批抖动：小 batch 下同步开销占比失控</h3>\n<p>批抖动指相邻解码步的 batch 组成剧烈变化，导致每层的偏斜指标在高低之间跳变，调度器频繁切换配置。每次切换都伴随 GPU 侧计数归约与主机侧决策两个同步点；batch 越小，这两个同步点占该层时延的比例越高。极端情况下，一次决策的开销超过它省下的核空转时间，吞吐反而下降。</p>\n<p>量化这个失败模式需要一个开销占比指标。设单层决策的固定开销为 T_sync（计数归约加主机往返），该层 GEMM 主体时延为 T_gemm，则：</p>\n<div class=\"formula\">$$\\eta_l=\\frac{T_{\\text{sync}}}{T_{\\text{sync}}+T_{\\text{gemm}}},\\quad \\text{若 } \\eta_l \\text{ 超过阈值则合并决策点}$$</div>\n<p>机制上的对策是跨层复用偏斜统计：不在每层都做归约，而是每隔若干层做一次，中间层沿用最近一次的直方图并按路由分布的缓慢漂移做外推。代价是中间层的配置可能滞后于真实偏斜，收益是同步点数量按复用窗口长度成比例下降。工程判断上，复用窗口应与 batch 大小的倒数挂钩——小 batch 拉长窗口，大 batch 缩短窗口，因为大 batch 下 T_gemm 足够大、η_l 天然较低。</p>\n<p>监控批抖动看两个量：单位时间内的配置切换次数，以及切换前后该层实测时延的差值。若切换频繁但时延差值为正（切换后更慢），说明代价模型系数失配，切换点判错，此时应冻结在线校正、回退到上一版系数并进入灰度观察。具体例子：在线服务在请求洪峰过后 batch 骤降，调度器仍按洪峰期学到的系数选择大 tile 配置，小 batch 下大 tile 的启动开销被放大，尾延迟出现尖刺；回滚动作是把系数回退到按 batch 分档维护的版本，而不是单一全局系数。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-44\">四十四 · 路由不均与尾延迟尖刺的联合诊断</h3>\n<p>路由不均本身是本方法要解决的问题，但它也会成为故障源：当某一层出现极端集中（单专家占比极高）而调度仍选择分组 GEMM，尾部专家组的空转会把该层拖成最慢分片；反之当分布接近均匀而调度选择单专家大 tile，大量小批专家被串行处理，同样产生尖刺。两类错误的共同特征是“配置与偏斜不匹配”，因此诊断要把 S_l 与选中配置 c 的对应关系画成二维分布，落在对角线之外的样本即为可疑决策。</p>\n<p>尾延迟尖刺的定位需要把端到端 P99 拆到层。做法是给每层 GEMM 打上时间戳，计算该层时延相对其滑动中位数的偏离倍数；偏离超过阈值的层即为尖刺来源层。再结合该层的 S_l 与 c，就能判断是路由漂移、配置判错还是带宽争抢。一个具体机制是给尖刺层做“配置回放”：用该层当时的直方图离线跑一遍三个候选配置的代价模型，看 argmin 是否与线上选择一致；不一致即证实系数失配。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要观测量</th><th>判据</th><th>回滚动作</th></tr></thead><tbody><tr><td>输出低频抖动</td><td>配置选择日志与校验和</td><td>Δ_max 超阈值</td><td>禁用该 c，固定 c0 重放</td></tr><tr><td>显存告警伴尖刺</td><td>ρ_l 与 TMA stall</td><td>ρ_l 连续偏高</td><td>收窄白名单至分组 GEMM</td></tr><tr><td>吞吐不升反降</td><td>η_l 与切换次数</td><td>η_l 超阈值</td><td>拉长复用窗口</td></tr><tr><td>P99 尖刺</td><td>层时延偏离倍数</td><td>偏离超阈值且 argmin 不一致</td><td>冻结在线校正，回退系数</td></tr></tbody></table>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-45\">四十五 · 监控埋点与回滚的分级设计</h3>\n<p>监控不能只埋吞吐与利用率，那两类指标对配置判错不敏感。必须埋的是决策链路：每层的直方图摘要（最大专家占比、基尼系数）、选中配置、代价模型预估时延与实测时延的比值。预估与实测的比值是系数健康度的直接读数，长期偏离 1 说明 α_c、β_c 需要重估。这个比值还能反过来喂给在线校正，形成闭环，但闭环本身要有阻尼，否则路由分布的一次瞬变会把系数带偏。</p>\n<p>回滚要分级，不能只有“全量回退到固定配置”这一档。第一级是单层白名单收窄，只影响可疑层；第二级是冻结在线校正、锁定上一版系数；第三级是关闭自适应、全局走固定分组 GEMM。三级回滚的代价依次上升：第一级损失局部吞吐，第二级损失对分布漂移的跟随能力，第三级回到固定 tile 的老问题——热门专家被尾部拖慢。分级的意义在于让运维能在不牺牲整体 SLO 的前提下切除病灶。</p>\n<p>回滚触发条件应写成可执行的布尔表达式而非人工判断。例如：连续 N 个观测窗口内，某层实测时延与预估时延的比值超过上界，且该层 P99 偏离中位数超过阈值，同时该层配置切换次数高于基线，三个条件同时成立才触发第一级回滚。三条件与门能有效过滤路由瞬变造成的误报。工程上还要保留一份“配置指纹”，记录每次决策时的候选 kernel 版本与量化块布局，回滚时按指纹恢复，避免 kernel 版本错配引入新的数值分叉。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-46\">四十六 · 候选 kernel 维护与编译产物膨胀的治理</h3>\n<p>多套候选 kernel 是本方法的结构性代价。每增加一个 tile 尺寸档位，就多一份编译产物、多一套调优参数、多一条数值路径需要做一致性验证。产物膨胀不只是磁盘问题，它拖慢部署流水线、拉长灰度周期，并在 kernel 选择逻辑里引入更多分支，分支本身在主机侧决策路径上就是开销。</p>\n<p>治理机制是给候选集设上限并按收益排序裁剪。用代价模型在代表性负载配方上跑一遍，统计每个候选配置被选中的频率与它相对默认配置的时延收益；收益低于阈值且选中频率低的配置直接下线。判据可写成：</p>\n<div class=\"formula\">$$\\text{keep } c \\text{ if } f_c\\cdot\\left(\\hat{T}(c_0)-\\hat{T}(c)\\right)&gt;\\gamma$$</div>\n<p>其中 f_c 为该配置在负载配方上的选中频率。这个判据把“偶尔有用但维护成本高”的配置剔出去，保留高频高收益的少数档位。代价是裁剪后某些边缘负载配方上的最优性下降，收益是部署复杂度与验证面收敛。具体例子：混合拆分配置只在极少数中间偏斜层被选中，选中频率低且收益有限，裁剪后由分组 GEMM 兜底，尾延迟略升但流水线显著简化。</p>\n<p>最后落在工程判断上：这套方法的失败模式几乎都指向同一个根因——决策链路与执行链路的信息不同步。计数归约在 GPU、决策在主机、执行又在 GPU，三段之间的同步点既是开销来源也是判错来源。因此诊断体系的第一优先级不是加指标，而是保证每一层的直方图摘要、选中配置、实测时延三者在同一时间戳下可关联；没有这个关联，精度回归、OOM、批抖动、路由不均与尾延迟尖刺五类症状就无法归因到具体决策，回滚也只能盲退。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-47\">四十七 · 切换点误判与同步开销：这套自适应调度的失效边界</h3>\n<p>偏斜感知调度的收益全部押在代价模型的一次判断上：若 $\\hat{T}(c)$ 的系数 $\\alpha_c,\\beta_c$ 与真实核行为脱节，切换点就会落在错误一侧。典型失效是路由分布快速漂移——在线服务里 batch 组成逐请求变化，热门专家集合在相邻层之间就可能翻转，而在线校正只能滞后跟随，于是热门专家被塞进分组 GEMM 的小 tile，尾部专家反而占着大 tile 空转，核利用率回退到固定配置水平，尾延迟被最慢分片重新拖住。判据本身也脆弱：$S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 只捕捉最大专家占比，当偏斜由两三个次热专家共同构成时该指标偏低，调度会误判为“接近均匀”而放弃单专家密集路径，收益消失。</p>\n<p>第二类失效来自决策链本身的代价。每层一次 GPU 侧计数归约加主机侧决策，等于在解码关键路径上插入同步点；小 batch 时单层计算只有几十微秒量级，归约与主机往返占比被放大，跨层复用偏斜统计正是为压制这一项，但复用窗口过长又会让统计过期，与漂移失效叠加。工程上应把“决策开销占单层时延比例”作为独立监控指标，超过阈值即退回固定配置或合并决策点，而不是继续调代价模型。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>处置</th></tr></thead><tbody><tr><td>吞吐回升但尾延迟尖刺</td><td>切换点误判，热门专家走了小 tile</td><td>冻结切换，回滚到单专家密集配置</td></tr><tr><td>小 batch 下时延整体抬升</td><td>每层归约与主机决策开销占比高</td><td>合并决策点、拉长跨层复用窗口</td></tr><tr><td>显存 OOM 或批抖动</td><td>多套候选 kernel 与重排缓冲挤占 KV cache</td><td>限制候选集、按 SLO 降批而非降精度</td></tr></tbody></table>\n<p>监控应围绕“分片利用率方差”而非平均利用率：平均值掩盖尾部空转，方差抬升才是切换失准的早期信号。回滚必须廉价——候选配置预先调优并维护多套 kernel，编译产物体积与调优负担是这套方案的固有成本，因此回滚路径要能在不改图、不重编译的前提下按层关闭自适应，退回固定 tile 与固定分组 GEMM；NVFP4/FP8 权重与激活降低搬运量，但精度问题一旦出现，优先怀疑重排后 tile 队列与量化 scale 的对齐，而非调度逻辑本身。</p>\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-48\">四十八 · 对照轴：把同族算法放到同一张坐标系上</h3>\n<p>偏斜感知自适应核调度不是孤立存在的一条路径，它和四条相邻路线共享同一个问题域：MoE 解码时每层专家 token 计数高度不均，热门专家挤满 tile、尾部专家空转。要在这五条路线之间做工程选择，先要把它们放到同一组对照轴上，而不是凭“谁更先进”来判断。可用的对照轴有四条：<strong>是否改变路由结果</strong>（容量因子路由与令牌丢弃会截断或丢弃 token，专家选择路由会改变选谁，本方法完全不碰路由，只改核形态）；<strong>是否改变 token 到专家的映射</strong>（无丢弃块稀疏分组 GEMM 重排分组但不丢弃，本方法进一步按偏斜度切换 tile 尺寸）；<strong>是否引入跨设备通信</strong>（分离式专家并行与专家并行 All-to-All 调度把专家搬上不同 rank，本方法留在单卡或单组内做核级决策）；<strong>同步开销落在哪一层</strong>（本方法在每层路由后插入 GPU 计数归约与主机决策，其他路线多数把开销放在批调度或通信域）。这四条轴决定了五条路线不是互斥替代，而是可以叠加的分层：路由层、分组层、核层、通信层各管一段。工程上真正要回答的是“我这一层的瓶颈在哪”，而不是“哪个算法最好”。</p>\n<p>把偏斜度指标 $S_l=\\max_e n_{l,e}/\\sum_e n_{l,e}$ 作为横轴，可以把选择问题讲清楚：$S_l$ 接近 $1/E$（$E$ 为专家数）时分布接近均匀，切换收益消失；$S_l$ 显著高于 $1/E$ 时，单专家大 tile 的收益才开始压过切换开销。代价模型的判据是 $\\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$，其中 $t_c$ 是配置 $c$ 的 tile 尺寸，$\\alpha_c,\\beta_c$ 由实测时延在线校正。这个式子的结构说明了一件事：候选配置之间的差异主要体现在“每个专家要开多少个 tile”这一项上，$\\alpha_c$ 是启动与同步的固定开销。因此选择本质上是在“减少 tile 数”与“增加固定开销”之间做权衡，而不是在两种 GEMM 实现之间做美学选择。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-49\">四十九 · 五条路线的分工与代价落点</h3>\n<p>逐条对照，每条路线的代价落点不同，这决定了它们各自适合放在流水线的哪一段。</p>\n<ul>\n<li><strong>容量因子路由与令牌丢弃</strong>：在路由阶段用容量因子截断每专家 token 上限，超出部分丢弃或绕过。它直接把 $n_{l,e}$ 压平，从源头消除偏斜，代价是丢弃 token 带来的精度损失与不可预测的输出质量。它适合对精度不敏感、吞吐优先的离线批处理，不适合 SLO 严格约束尾延迟的在线解码——丢弃会让部分请求的输出退化，而尾延迟并不因此收敛。</li>\n<li><strong>专家选择路由</strong>：让专家反向选择 token，天然带负载均衡约束，能把 $S_l$ 压到接近均匀。代价是路由逻辑本身变复杂、每层多一次全局排序或匹配，且改变了模型语义，需要重新校准。它适合从模型侧就接受路由改造的场景，不适合已定型、只能改推理栈的部署。</li>\n<li><strong>无丢弃块稀疏分组 GEMM</strong>：保留全部 token，按块把尾部专家合并成组执行，消除空转但不切换 tile 尺寸。代价是分组启动与尾组流水掩盖，收益在中等偏斜时最明显；偏斜极高时热门专家仍受小 tile 限制。</li>\n<li><strong>分离式专家并行与专家并行 All-to-All 调度</strong>：把专家分布到多 rank，用 NVLink 5 与 NCCL/NIXL 搬运 token。它解决的是单卡放不下全部专家或单卡算力不足的问题，代价是 All-to-All 通信延迟进入关键路径，在解码小 batch 下通信开销占比高。</li>\n<li><strong>本方法（偏斜感知自适应核调度）</strong>：不动路由、不动 token 集合、不动通信拓扑，只在核层按层切换 tile 与分组形态。代价是每层一次 GPU 计数归约加主机决策的同步点，以及多套候选 kernel 的维护成本。</li>\n</ul>\n<p>一个具体例子可以说明分层关系：某在线服务 batch 内 $S_l$ 达到 0.4 量级（专家数远大于 2，均匀分布应在 0.05 上下），此时若只上无丢弃分组 GEMM，热门专家仍被小 tile 切成多块，单层时延被 tile 数 $\\sum_e\\lceil n_{l,e}/t_c\\rceil$ 主导；若叠加本方法，热门专家走大 tile 单专家密集 GEMM，尾部走分组 GEMM，tile 总数下降，单层时延回落。而如果该模型专家总量超出单卡显存，则必须先上分离式专家并行，本方法退化为每个 rank 内部的核选择，收益被通信延迟稀释。这就是“先定层、再选算法”的实际含义。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-50\">五十 · 决策表：按条件选路线</h3>\n<p>下表把适用条件压缩成可执行的判断，每一行对应一个工程前提，而不是一个偏好。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>条件</th><th>首选路线</th><th>不选本方法的原因</th><th>代价落点</th></tr>\n</thead>\n<tbody>\n<tr><td>精度不可让步，token 不可丢</td><td>无丢弃分组 GEMM + 本方法叠加</td><td>—</td><td>分组启动开销、每层同步</td></tr>\n<tr><td>可接受输出质量退化，吞吐优先</td><td>容量因子路由与令牌丢弃</td><td>丢弃已压平偏斜，切换收益消失</td><td>精度损失</td></tr>\n<tr><td>模型侧可改路由语义</td><td>专家选择路由</td><td>路由已均衡，$S_l\\to 1/E$</td><td>路由计算与重校准</td></tr>\n<tr><td>专家总量超单卡显存/算力</td><td>分离式专家并行</td><td>通信在关键路径，核选择收益被稀释</td><td>All-to-All 延迟</td></tr>\n<tr><td>偏斜显著且 batch 组成可观测</td><td>本方法</td><td>—</td><td>每层归约+决策同步、多 kernel 维护</td></tr>\n<tr><td>batch 极小（同步占比高）</td><td>合并决策点或退回固定配置</td><td>每层同步开销压过 tile 收益</td><td>同步点占比</td></tr>\n<tr><td>路由分布快速漂移</td><td>本方法 + 在线校正，或退回固定分组</td><td>系数失配导致切换点误判</td><td>尾延迟放大风险</td></tr>\n</tbody>\n</table>\n<p>表里最容易被误读的是最后两行。小 batch 下每层 GPU 计数归约加主机决策的固定开销 $\\alpha_c$ 在总时延中占比升高，此时正确做法不是硬上自适应，而是把多层决策合并成一个决策点，或者干脆退回固定分组 GEMM，把同步点从每层一次降到每若干层一次。路由分布快速漂移时，$\\alpha_c,\\beta_c$ 的在线校正跟不上，切换点判断错误会让核利用率回退甚至尾延迟放大——这时的工程判断是给校正加阻尼、限制单次切换幅度，而不是追求每层最优。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-51\">五十一 · 适用条件的量化边界</h3>\n<p>把“偏斜显著”变成可判定的边界，需要两个量：偏斜度 $S_l$ 与每层决策开销占比。前者决定切换有没有收益，后者决定收益能不能覆盖成本。收益侧的粗略估计是：固定小 tile 下 tile 总数为 $\\sum_e\\lceil n_{l,e}/t_{\\text{small}}\\rceil$，切到热门专家大 tile 后，热门专家贡献的 tile 数从 $\\lceil n_{\\text{hot}}/t_{\\text{small}}\\rceil$ 降为 $\\lceil n_{\\text{hot}}/t_{\\text{large}}\\rceil$，差值乘以单 tile 时间 $t^{\\text{tile}}_c$ 就是毛收益；成本侧是每层归约与决策的固定时延。当 $S_l$ 接近 $1/E$ 时，热门专家与尾部专家 token 数相当，大 tile 的收益被尾部仍需小 tile 的事实抵消，净收益趋零。因此边界可以写成：只有当热门专家 token 数足以填满至少一个大 tile、且尾部专家合并后仍能形成有效分组时，切换才成立。</p>\n<div class=\"formula\">$$S_l=\\frac{\\max_e n_{l,e}}{\\sum_e n_{l,e}},\\qquad \\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\left\\lceil\\frac{n_{l,e}}{t_c}\\right\\rceil,\\qquad c^\\star=\\arg\\min_c\\hat{T}(c)$$</div>\n<p>这个判据的工程含义是：$c^\\star$ 的选择对 $\\beta_c$ 敏感，而 $\\beta_c$ 是单 tile 时间，随 tile 尺寸变化——大 tile 的 $\\beta_c$ 更大但 tile 数更少，小 tile 反之。在线校正的作用就是让这两个系数跟随实际硬件与量化格式（NVFP4/FP8 下搬运量不同，$\\beta_c$ 随之变化）漂移。规模上限则受两件事约束：候选配置的调优成本（每多一套 kernel 就多一份编译产物与调优负担）与同步开销（每层一个同步点，层数越多累计越可观）。因此本方法在层数深、专家多、batch 组成动态的在线解码里收益最实，在层数浅或 batch 固定的场景里应让位给固定配置。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-52\">五十二 · 组合而非替代：叠加顺序与工程判断</h3>\n<p>五条路线的关系是分层叠加，叠加顺序有讲究。第一层是路由层：若精度允许，容量因子或专家选择路由先把 $S_l$ 压下来，此时核层自适应的收益空间被压缩，应评估是否还值得维护多套 kernel。第二层是分组层：无丢弃块稀疏分组 GEMM 保证不丢 token 且尾部不空转，它是本方法的前置条件——本方法正是在分组 GEMM 与小 tile 之间做选择，没有分组 GEMM 这套候选，切换就退化为“大 tile 对固定小 tile”的二选一。第三层是核层：本方法按层偏斜度在单专家密集 GEMM、分组 GEMM、混合拆分之间切换，用 tcgen05 的 TMA 加载权重与激活、mbarrier 流水掩盖尾组启动延迟。第四层是通信层：分离式专家并行决定 token 是否跨 rank，一旦跨 rank，核层决策只能在每个 rank 内部做，且 All-to-All 延迟进入关键路径，本方法的同步开销要与通信开销一起核算。</p>\n<p>一个具体的工程判断：当部署已经采用分离式专家并行、且 All-to-All 延迟占单层时延的可观比例时，把工程投入放在通信调度（NIXL 传输、All-to-All 与计算重叠）上的回报高于在核层做偏斜自适应；反之，当专家全部驻留单卡或单组、瓶颈明确落在尾部专家空转时，本方法是直接命中瓶颈的那一层。判断依据不是算法的新旧，而是单层时延分解里 tile 空转与同步开销各占多少——若空转占比高而同步开销可被跨层复用摊薄，选本方法；若同步开销在小 batch 下已经压过空转收益，选合并决策点或固定分组。这条判断线也解释了为什么本方法的适用边界写得窄：它只对“偏斜显著且 batch 组成可观测”的解码场景负责，其余场景应交还给相邻层。</p>\n<p>最后落到机制上：无论选哪条路线，最终都要在每层路由完成后拿到专家 token 直方图才能做决策，差别只在于这个直方图被谁消费——被容量因子消费就是丢弃，被分组 GEMM 消费就是合并，被本方法消费就是切换 tile。跨层复用偏斜统计、把决策点从每层一次降为每若干层一次，是这套分层在工程上能站住的前提；而候选 kernel 的调优成本与编译产物体积，则是选择本方法时必须预先计入的固定投入。</p>\n\n<h3 id=\"alg-moe-skew-adaptive-dispatch-sec-53\">五十三 · 偏斜自适应调度的失效边界与同族选型</h3>\n<p>这套按层切换核形态的方案，其收益全部押在“偏斜显著且可观测”这一个前提上。判据本身很直白：<span class=\"formula\">$$S_l=\\frac{\\max_e n_{l,e}}{\\sum_e n_{l,e}},\\quad \\hat{T}(c)=\\alpha_c+\\beta_c\\sum_e\\lceil n_{l,e}/t_c\\rceil$$</span> 当 $S_l$ 逼近 $1/E$（$E$ 为专家数）时，单专家大 tile 与分组 GEMM 的预估时延差被 $\\alpha_c$ 项吞掉，切换只剩同步开销。因此均匀路由的层应当直接锁定一种配置、跳过决策点，把省下的归约与主机往返留给真正偏斜的层。失效条件有三类：一是小 batch 解码，每层计数归约加主机决策的固定开销在总时延中占比抬升，此时应把决策点按若干层合并、复用偏斜统计；二是路由分布快速漂移，在线校正的 $\\alpha_c,\\beta_c$ 跟不上，切换点判错会让核利用率回退、尾延迟反而放大；三是候选 kernel 维护成本，多套配置的调优与编译产物体积是长期负担，配置数必须设上限。</p>\n<p>与相邻算法对照，选型不看单点峰值而看“偏斜是否值得被观测”。固定 tile 分组 GEMM 的优点是零决策开销、产物单一，代价是热门专家被尾部专家拖住，适合偏斜温和或 batch 组成稳定的离线批推理；固定大 tile 单专家密集 GEMM 在极端偏斜下最省，但对中等偏斜层会浪费尾部算力；混合拆分介于两者之间，实现复杂度最高。本方案的位置是“按层在两端之间摆动”，只在偏斜指标跨越切换点时兑现收益。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>首选</th><th>理由与代价</th></tr></thead><tbody><tr><td>高并发短输出、batch 组成动态</td><td>偏斜自适应切换</td><td>吞吐与尾延迟双约束下收益最大；付出每层同步与多套 kernel 维护</td></tr><tr><td>小 batch、层数深</td><td>固定分组 GEMM + 跨层合并决策</td><td>决策开销占比过高，合并决策点后自适应才有意义</td></tr><tr><td>路由接近均匀</td><td>固定配置，关闭切换</td><td>$S_l\\to1/E$，切换收益消失，只剩同步成本</td></tr><tr><td>分布漂移剧烈</td><td>保守固定配置或加长校正窗口</td><td>系数失配导致切换点误判，尾延迟放大风险高于收益</td></tr></tbody></table>\n<p>工程判断落在决策粒度上：把“每层一次”放宽为“每 N 层一次 + 跨层复用直方图”，用少量精度换取同步开销的下降，是这套方案在深堆叠模型上能否成立的关键；而候选配置数量应压到两到三套，超出即失去可维护性。量化侧用 NVFP4/FP8 压低权重与激活搬运量后，$\\beta_c$ 中的搬运项变小，切换点会向大 tile 一侧偏移，校正系数必须随量化档位重估，否则判据系统性偏保守。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 专家并行与All-to-All通信</td></tr><tr><td>解决什么</td><td>MoE 解码 batch 内路由高度偏斜，少数热门专家承载大部分 token，固定 tile 尺寸与固定分组 GEMM…</td></tr><tr><td>一句话机制</td><td>运行时按每层路由计数的偏斜度（基尼系数/最大专家占比）在多个候选 kernel 配置间切换：偏斜高时走大 tile 单…</td></tr><tr><td>代价与失效</td><td>每层需 GPU 侧计数归约与主机侧决策，引入额外同步点，小 batch 下开销占比高；候选配置需预先调优并维护多套 kernel，工程复杂…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-moe-skew-adaptive-dispatch · 共 8 个片段</p>\n";break;}}})();
